                        ProgressView()
                            .scaleEffect(1.5)
                    } else {
                        // Apple 登录按钮
                        SignInWithAppleButton(
                            .signIn,
                            onRequest: { request in
                                // 可以在这里配置请求，但 AuthManager 中已配置
                            },
                            onCompletion: { result in
                                // AuthManager 会通过代理处理结果，这里不需要代码
                            }
                        )
                        .onTapGesture {
                            // 实际的逻辑由 AuthManager 触发
                            authManager.signInWithApple()
                        }
                        // 5. 按钮样式适配：亮色模式用黑按钮，深色模式用白按钮
                        .signInWithAppleButtonStyle(colorScheme == .light ? .black : .white)
                        .frame(height: 50)
                        .cornerRadius(10)
                        // 添加阴影让按钮更有层次感
                        .shadow(color: Color.black.opacity(0.1), radius: 4, x: 0, y: 2)
                    }

                    // 错误信息
                    if let errorMessage = authManager.errorMessage {
                        Text(errorMessage)
                            .foregroundColor(.red)
                            .font(.caption)
                            .multilineTextAlignment(.center)
                    }
                }
                .padding(.horizontal, 40)

                Spacer()

                // 关闭按钮
                Button("稍后再说") {
                    // 【核心修改】这里仅关闭视图，后续的支付跳转逻辑由父视图的 onDismiss 处理
                    dismiss()
                }
                .font(.subheadline)
                .foregroundColor(.secondary) // 改为次级颜色
                .padding(.bottom, 20)
            }
        }
        // 移除 .preferredColorScheme(.dark) 以允许系统切换
        .onChange(of: authManager.isLoggedIn) { _, newValue in
            if newValue {
                dismiss()
            }
        }
    }
}

