            Button("确定", role: .cancel) {
                // 如果验证成功，关闭订阅页面
                if authManager.isSubscribed {
                    dismiss()
                }
            }
        } message: {
            Text(redeemMessage)
        }
        // 【新增】登录弹窗
        .sheet(isPresented: $showLoginSheet) {
            LoginView()
        }
        .onChange(of: authManager.isLoggedIn) { _, newValue in
            // 当监测到登录状态变为 true
            if newValue == true {
                // 1. 关闭登录弹窗
                if showLoginSheet {
                    showLoginSheet = false
                }

                // =========== 【4. 新增】登录成功后的自动跳转逻辑 ===========
                if pendingRedeemAfterLogin {
                    print("登录成功，检测到待处理的兑换请求，延迟弹出输入框...")
                    pendingRedeemAfterLogin = false // 重置标记

                    // 【关键】必须加一点延迟，等待 LoginView 的关闭动画完成
                    // 否则 Sheet 关闭和 Alert 弹出同时发生可能会冲突导致 Alert 弹不出来
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                        showRedeemSheet = true
                    }
                }
            }
        }
    }

    // =========== 【3. 新增】处理连按触发逻辑 ===========
    private func handleSecretTrigger() {
        if authManager.isLoggedIn {
            // 如果已登录，直接显示兑换输入框
            showRedeemSheet = true
        } else {
            // 如果未登录，先标记“待兑换”，然后弹出登录页
            print("触发彩蛋：未登录，跳转登录页")
            pendingRedeemAfterLogin = true
            showLoginSheet = true
        }
    }

    // 【修改】处理购买：先检查登录
    private func handlePurchase() {
        // 1. 检查是否已登录
        guard authManager.isLoggedIn else {
            // 未登录 -> 弹出登录页
            showLoginSheet = true
            return
        }

        // 2. 已登录 -> 执行原有购买逻辑
        isPurchasing = true
        Task {
            do {
                try await authManager.purchaseSubscription()
                await MainActor.run {
                    isPurchasing = false
                    // 【核心修改】
                    // 只有当订阅状态确实变为 true (购买成功) 时，才关闭弹窗。
                    // 如果用户取消了支付 (isSubscribed 仍为 false)，则不关闭，保留在当前页面。
                    if authManager.isSubscribed {
                        dismiss()
                    } else {
                        print("用户取消或未完成支付，保留订阅页面")
                    }
                }
            } catch {
                await MainActor.run {
                    isPurchasing = false
                    errorMessage = error.localizedDescription
                    showError = true
                }
            }
        }
    }

    // 【修改】处理恢复购买：先检查登录
    private func performRestore() {
        // 1. 检查是否已登录
        guard authManager.isLoggedIn else {
            // 未登录 -> 弹出登录页
            showLoginSheet = true
            return
        }

        // 2. 已登录 -> 执行原有恢复逻辑
        isRestoring = true
        Task {
            do {
                // 调用 AuthManager 的恢复方法
                try await authManager.restorePurchases()
                await MainActor.run {
                    isRestoring = false
                    if authManager.isSubscribed {
                        restoreMessage = "成功恢复订阅！您现在可以无限制访问数据。"
                    } else {
                        restoreMessage = "未发现有效的订阅记录。"
                    }
                    showRestoreAlert = true
                }
            } catch {
                await MainActor.run {
                    isRestoring = false
                    restoreMessage = "恢复失败: \(error.localizedDescription)"
                    showRestoreAlert = true
                }
            }
        }
    }

    // 【新增】执行兑换码验证逻辑
    private func performRedeem() {
        // 简单的本地判空
        guard !redeemCodeInput.isEmpty else { return }

        // 2. 【新增】检查是否已登录 (如果服务器需要绑定User ID)
        guard authManager.isLoggedIn else {
            showLoginSheet = true
            return
        }

        isRedeeming = true

        Task {
            do {
                // 调用 AuthManager 的方法请求服务器
                let success = try await authManager.redeemInviteCode(redeemCodeInput)

                await MainActor.run {
                    isRedeeming = false
                    if success {
                        redeemMessage = "验证成功！您已获得无限访问权限。"
                        redeemCodeInput = "" // 清空输入
                    }
                    showRedeemResultAlert = true
                }
            } catch {
                await MainActor.run {
                    isRedeeming = false
                    // 显示具体的错误信息（例如：无效的邀请码）
                    redeemMessage = "验证失败: \(error.localizedDescription)"
                    showRedeemResultAlert = true
                }
            }
        }
    }
}

import SwiftUI
import Charts // 导入苹果原生的 Charts 框架

// MARK: - CompareView (此视图基本不变，仅导航目标有变化)
struct CompareView: View {
    @Environment(\.presentationMode) var presentationMode
    @EnvironmentObject var dataService: DataService

    // 【新增】权限管理
    @EnvironmentObject var authManager: AuthManager
    @EnvironmentObject var usageManager: UsageManager
    // 【修改】移除 showLoginSheet
    @State private var showSubscriptionSheet = false

    let initialSymbol: String
    private let maxSymbols = 10

    @State private var symbols: [String] = []
    @State private var endDate: Date = Date()
    @State private var errorMessage: String? = nil
    @State private var navigateToComparison = false
    @State private var showAlert = false

    // Start/End Date pickers expansion states
    @State private var isStartDateExpanded = false
    @State private var isEndDateExpanded = false

    // Track focused input field
    @FocusState private var focusedField: Int?

    // Default start date: year 2014
    @State private var startDate: Date = Calendar.current.date(from: DateComponents(year: 2024))!

    var body: some View {
        VStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 16) {

                    // Comparison button
                    Button(action: startComparison) {
                        Text("开始比较")
                            .foregroundColor(.white)
                            .padding()
                            .frame(maxWidth: .infinity)
                            .background(Color.blue)
                            .cornerRadius(8)
                    }

                    // Collapsible date pickers
                    Group {
                        DisclosureGroup(isExpanded: $isStartDateExpanded) {
                            DatePicker("", selection: $startDate, displayedComponents: .date)
                                .datePickerStyle(GraphicalDatePickerStyle())
                                .padding(.vertical)
                        } label: {
                            HStack {
                                Text("开始日期:")
                                    .font(.headline)
                                Spacer()
                                Text(startDate.formatted(date: .abbreviated, time: .omitted))
                                    .foregroundColor(.gray)
                            }
                        }

                        DisclosureGroup(isExpanded: $isEndDateExpanded) {
                            DatePicker("", selection: $endDate, displayedComponents: .date)
                                .datePickerStyle(GraphicalDatePickerStyle())
                                .padding(.vertical)
                        } label: {
                            HStack {
                                Text("结束日期:")
                                    .font(.headline)
                                Spacer()
                                Text(endDate.formatted(date: .abbreviated, time: .omitted))
                                    .foregroundColor(.gray)
                            }
                        }
                    }

                    // Stock symbol input fields
                    VStack(alignment: .leading, spacing: 12) {
                        ForEach(0..<symbols.count, id: \.self) { index in
                            HStack {
                                CustomTextField(
                                    placeholder: "股票代码 \(index + 1)",
                                    text: $symbols[index],
                                    onClear: {
                                        focusedField = index
                                    }
                                )
                                .focused($focusedField, equals: index)

                                // Remove row button
                                if symbols.count > 1 {
                                    Button {
                                        symbols.remove(at: index)
                                    } label: {
                                        Image(systemName: "minus.circle")
                                            .foregroundColor(.red)
                                    }
                                }
                            }
                        }

                        // "Add symbol" button
                        if symbols.count < maxSymbols {
                            Button {
                                let newIndex = symbols.count
                                symbols.append("")
                                DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {
                                    focusedField = newIndex
                                }
                            } label: {
                                HStack {
                                    Image(systemName: "plus.circle")
                                    Text("添加股票代码")
                                }
                            }
                            .foregroundColor(.blue)
                        }
                    }

                    // Error message
                    if let errorMessage {
                        Text(errorMessage)
                            .foregroundColor(.red)
                            .font(.footnote)
                    }
                }
                .padding()
            }
            Spacer()
        }
        .onAppear {
            if symbols.isEmpty {
                if initialSymbol.isEmpty {
                    symbols.append("")
                } else {
                    symbols.append(initialSymbol)
                }
                symbols.append("")

                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                    focusedField = initialSymbol.isEmpty ? 0 : 1
                }
            }
        }
        .navigationDestination(isPresented: $navigateToComparison) {
            // 导航目标变为新的 ComparisonChartView
            ComparisonChartView(symbols: symbols, startDate: startDate, endDate: endDate)
        }
        .alert(isPresented: $showAlert) {
            Alert(title: Text("错误"), message: Text(errorMessage ?? "未知错误"), dismissButton: .default(Text("确定")))
        }
        // 【修改】移除了 LoginView 的 sheet
        .sheet(isPresented: $showSubscriptionSheet) { SubscriptionView() }
    }

    func formatSymbol(_ symbol: String) -> String {
        guard let url = Bundle.main.url(forResource: "Sectors_All", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let sectorData = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: [String]] else {
            return symbol
        }

        for (_, symbolList) in sectorData {
            for originalJsonSymbol in symbolList {
                if originalJsonSymbol == symbol {
                    return originalJsonSymbol
                }
            }
        }
        return symbol
    }

    private func startComparison() {
        // 【核心修改】
        // 这里使用 .compare 动作。
        // 只有当用户点击这个按钮，且通过了检查，才会扣除点数。
        // 首页点击进入 CompareView 页面时不扣点（因为 SearchContentView 里只是纯导航，没调用 UsageManager）。
        guard usageManager.canProceed(authManager: authManager, action: .compare) else {
            showSubscriptionSheet = true
            return
        }

        errorMessage = nil
        let trimmedSymbols = symbols.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
        guard !trimmedSymbols.isEmpty else { errorMessage = "请至少输入一个股票代码"; showAlert = true; return }
        if trimmedSymbols.count > maxSymbols { errorMessage = "最多只能比较 \(maxSymbols) 个股票代码"; showAlert = true; return }
        guard startDate <= endDate else { errorMessage = "开始日期必须早于或等于结束日期"; showAlert = true; return }
        symbols = trimmedSymbols.map { formatSymbol($0) }
        navigateToComparison = true
    }
}

