    // 4. 获取财报数据 (Async)
    func fetchEarningData(forSymbol symbol: String) async -> [EarningData] {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/earning") else { return [] }
        components.queryItems = [URLQueryItem(name: "symbol", value: symbol)]

        guard let url = components.url else { return [] }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let results = try JSONDecoder().decode([EarningData].self, from: data)
            return results
        } catch {
            print("Network error fetching earning data: \(error)")
            return []
        }
    }

    // 5. 获取收盘价 (Async)
    func fetchClosingPrice(forSymbol symbol: String, onDate date: Date, tableName: String) async -> Double? {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/closing_price") else { return nil }

        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"

        components.queryItems = [
            URLQueryItem(name: "symbol", value: symbol),
            URLQueryItem(name: "date", value: formatter.string(from: date)),
            URLQueryItem(name: "table", value: tableName)
        ]

        guard let url = components.url else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let response = try JSONDecoder().decode([String: Double?].self, from: data)
            return response["price"] ?? nil
        } catch {
            print("Network error fetching closing price: \(error)")
            return nil
        }
    }

    // 6. 检查表是否有 Volume (Async - 实际逻辑在服务器端处理，这里仅保留接口或简化)
    // 由于服务器端的 query_historical 会自动处理 volume 字段，
    // 客户端其实不需要显式检查。为了兼容旧代码调用，可以返回 true (假设服务器处理) 或移除调用。
    // 这里我们简单返回 true，因为服务器 API 已经封装了 schema 检查。
    func checkIfTableHasVolume(tableName: String) async -> Bool {
        return true 
    }

    // 7. 获取期权汇总数据 (Async) - 新增
    func fetchOptionsSummary(forSymbol symbol: String) async -> OptionsSummary? {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/options_summary") else { return nil }
        components.queryItems = [URLQueryItem(name: "symbol", value: symbol)]

        guard let url = components.url else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let result = try JSONDecoder().decode(OptionsSummary.self, from: data)
            return result
        } catch {
            print("Network error fetching options summary: \(error)")
            return nil
        }
    }

    // 8. 获取期权历史价格数据 (Async) - 新增
    func fetchOptionsHistory(forSymbol symbol: String) async -> [OptionHistoryItem] {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/options_price_history") else { return [] }
        components.queryItems = [URLQueryItem(name: "symbol", value: symbol)]

        guard let url = components.url else { return [] }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let results = try JSONDecoder().decode([OptionHistoryItem].self, from: data)
            return results
        } catch {
            print("Network error fetching options history: \(error)")
            return []
        }
    }
}

import SwiftUI
import Charts
import Foundation

// MARK: - 【重构】期权价格历史图表组件
struct OptionsHistoryChartView: View {
    let symbol: String

    // 状态管理
    @State private var historyData: [DatabaseManager.OptionHistoryItem] = []
    @State private var selectedTimeRange: TimeRangeOption = .threeMonths
    @State private var isLoading = false

    // 定义时间范围枚举
    enum TimeRangeOption: String, CaseIterable, Identifiable {
        case threeMonths = "3M"
        case sixMonths = "6M"
        case oneYear = "1Y"
        case twoYears = "2Y"
        case fiveYears = "5Y"
        case tenYears = "10Y"

        var id: String { self.rawValue }

        var monthsBack: Int {
            switch self {
            case .threeMonths: return 3
            case .sixMonths: return 6
            case .oneYear: return 12
            case .twoYears: return 24
            case .fiveYears: return 60
            case .tenYears: return 120
            }
        }
    }

    // 过滤后的数据
    var filteredData: [DatabaseManager.OptionHistoryItem] {
        let calendar = Calendar.current
        guard let startDate = calendar.date(byAdding: .month, value: -selectedTimeRange.monthsBack, to: Date()) else {
            return historyData
        }
        return historyData.filter { $0.date >= startDate }
    }

    var body: some View {
        VStack(spacing: 12) {
            // 1. 图表主体区域
            mainChartArea

            // 2. 时间切换条
            timeRangeSelector
        }
        .task {
            await loadData()
        }
    }

    // 拆分出图表主体
    @ViewBuilder
    private var mainChartArea: some View {
        ZStack {
            RoundedRectangle(cornerRadius: 16)
                .fill(Color(UIColor.secondarySystemGroupedBackground))
                .shadow(color: Color.black.opacity(0.05), radius: 5, x: 0, y: 2)

            if isLoading {
                ProgressView()
            } else if historyData.isEmpty {
                Text("暂无历史价格数据")
                    .font(.caption)
                    .foregroundColor(.secondary)
            } else if filteredData.isEmpty {
                Text("该时间段内无数据")
                    .font(.caption)
                    .foregroundColor(.secondary)
            } else {
                chartContent
            }
        }
        .frame(height: 220)
        .padding(.horizontal)
    }

    // 拆分出具体的 Chart 代码
    private var chartContent: some View {
        Chart {
            ForEach(filteredData) { item in
                BarMark(
                    x: .value("Date", item.date),
                    y: .value("Price", item.price)
                )
                // 【注意】移除了 .width 修饰符以解决 "has no member width" 报错。
                // Charts 会自动根据数据密度调整柱子宽度。
                .foregroundStyle(barGradient(for: item.price))
            }

            // 0轴基准线
            RuleMark(y: .value("Zero", 0))
                .lineStyle(StrokeStyle(lineWidth: 1, dash: [5]))
                .foregroundStyle(.gray.opacity(0.5))
        }
        .chartYAxis {
            AxisMarks(position: .leading)
        }
        .chartXAxis {
            AxisMarks(values: .automatic) { value in
                AxisGridLine()
                AxisTick()
                if let date = value.as(Date.self) {
                    AxisValueLabel {
                        Text(date, format: .dateTime.month().year(.twoDigits))
                            .font(.caption2)
                    }
                }
            }
        }
        .padding(.vertical, 16)
        .padding(.horizontal, 8)
    }

    // 辅助函数：生成渐变色
    private func barGradient(for price: Double) -> LinearGradient {
        let isPositive = price >= 0
        let colors: [Color] = isPositive
            ? [.red.opacity(0.8), .red.opacity(0.4)]
            : [.green.opacity(0.8), .green.opacity(0.4)]

        return LinearGradient(
            colors: colors,
            startPoint: isPositive ? .bottom : .top,
            endPoint: isPositive ? .top : .bottom
        )
    }

    // 拆分出时间选择器
    private var timeRangeSelector: some View {
        HStack(spacing: 0) {
            ForEach(TimeRangeOption.allCases) { option in
                Button(action: {
                    withAnimation(.easeInOut) {
                        selectedTimeRange = option
                    }
                }) {
                    Text(option.rawValue)
                        .font(.system(size: 13, weight: .medium))
                        .frame(maxWidth: .infinity)
                        .padding(.vertical, 8)
                        .background(
                            selectedTimeRange == option
                            ? Color.blue.opacity(0.15)
                            : Color.clear
                        )
                        .foregroundColor(
                            selectedTimeRange == option
                            ? .blue
                            : .secondary
                        )
                        .clipShape(RoundedRectangle(cornerRadius: 8))
                }
            }
        }
        .padding(4)
        .background(Color(UIColor.tertiarySystemFill))
        .cornerRadius(10)
        .padding(.horizontal)
    }

    private func loadData() async {
        isLoading = true
        let rawData = await DatabaseManager.shared.fetchOptionsHistory(forSymbol: symbol)
        await MainActor.run {
            self.historyData = rawData
            self.isLoading = false
        }
    }
}

// MARK: - 【重构】界面 A：期权 Symbol 列表
struct OptionsListView: View {
    @EnvironmentObject var dataService: DataService
    @EnvironmentObject var authManager: AuthManager
    @EnvironmentObject var usageManager: UsageManager

    @State private var selectedSymbol: String?
    @State private var navigateToDetail = false
    @State private var showSubscriptionSheet = false

    // 【新增】控制跳转到榜单页面
    @State private var navigateToRank = false

    var sortedSymbols: [String] {
        let allSymbols = dataService.optionsData.keys
        let noCapSymbols = allSymbols.filter { symbol in
            guard let item = dataService.marketCapData[symbol.uppercased()] else { return true }
            return item.rawMarketCap <= 0
        }.sorted()

        let hasCapSymbols = allSymbols.filter { symbol in
            guard let item = dataService.marketCapData[symbol.uppercased()] else { return false }
            return item.rawMarketCap > 0
        }.sorted { s1, s2 in
            let cap1 = dataService.marketCapData[s1.uppercased()]?.rawMarketCap ?? 0
            let cap2 = dataService.marketCapData[s2.uppercased()]?.rawMarketCap ?? 0
            return cap1 > cap2
        }
        return noCapSymbols + hasCapSymbols
    }

    var body: some View {
        List {
            if sortedSymbols.isEmpty {
                Text("暂无期权异动数据")
                    .foregroundColor(.secondary)
            } else {
                ForEach(sortedSymbols, id: \.self) { symbol in
                    OptionListRow(symbol: symbol) {
                        handleSelection(symbol)
                    }
                }
            }
        }
        .navigationTitle("期权异动")
        .navigationBarTitleDisplayMode(.inline)
        // 【新增】右上角按钮
        .toolbar {
            ToolbarItem(placement: .navigationBarTrailing) {
                Button(action: {
                    // 这里原来是 .openSpecialList，改为 .viewOptionsRank
                    if usageManager.canProceed(authManager: authManager, action: .viewOptionsRank) { 
                        self.navigateToRank = true
                    } else {
                        self.showSubscriptionSheet = true
                    }
                }) {
                    // 【修改点】设计漂亮的胶囊按钮
                    HStack(spacing: 4) {
                        // 加个小图标增加精致感
                        Image(systemName: "chart.line.uptrend.xyaxis")
                            .font(.system(size: 12, weight: .bold))

                        Text("涨跌预测榜")
                            .font(.system(size: 13, weight: .bold))
                    }
                    .padding(.vertical, 6)
                    .padding(.horizontal, 12)
                    .foregroundColor(.white)
                    .background(
                        // 蓝紫色渐变，体现“预测/智能”的感觉
                        LinearGradient(
                            gradient: Gradient(colors: [Color.blue, Color.indigo]),
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                    )
                    .clipShape(Capsule()) // 胶囊圆角
                    .shadow(color: Color.blue.opacity(0.3), radius: 4, x: 0, y: 2) // 柔和阴影
                    .overlay(
                        // 增加一道淡淡的高光描边，增加立体感
                        Capsule()
                            .stroke(Color.white.opacity(0.2), lineWidth: 1)
                    )
