            let container = try decoder.container(keyedBy: CodingKeys.self)
            price = try container.decode(Double.self, forKey: .price)
            let dateString = try container.decode(String.self, forKey: .date)
            let formatter = DateFormatter()
            formatter.dateFormat = "yyyy-MM-dd"
            if let date = formatter.date(from: dateString) {
                self.date = date
            } else {
                self.date = Date.distantPast
            }
        }
    }

    enum DateRangeInput {
        case timeRange(TimeRange)
        case customRange(start: Date, end: Date)
    }

    // MARK: - API Requests

    // 1. 获取所有市值数据 (Async)
    func fetchAllMarketCapData(from tableName: String) async -> [MarketCapInfo] {
        // tableName 参数在服务器端目前硬编码为 MNSPP，但保留参数以兼容
        guard let url = URL(string: "\(serverBaseURL)/query/market_cap") else { return [] }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let results = try JSONDecoder().decode([MarketCapInfo].self, from: data)
            return results
        } catch {
            print("Network error fetching market cap: \(error)")
            return []
        }
    }

    // 2. 获取最新成交量 (Async)
    func fetchLatestVolume(forSymbol symbol: String, tableName: String) async -> Int64? {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/latest_volume") else { return nil }
        components.queryItems = [
            URLQueryItem(name: "symbol", value: symbol),
            URLQueryItem(name: "table", value: tableName)
        ]

        guard let url = components.url else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let response = try JSONDecoder().decode([String: Int64?].self, from: data)
            return response["volume"] ?? nil
        } catch {
            print("Network error fetching volume: \(error)")
            return nil
        }
    }

    // 3. 获取历史数据 (Async)
    func fetchHistoricalData(
        symbol: String,
        tableName: String,
        dateRange: DateRangeInput
    ) async -> [PriceData] {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/historical") else { return [] }

        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"

        let (startDate, endDate): (Date, Date) = {
            switch dateRange {
            case .timeRange(let timeRange):
                return (timeRange.startDate, Date())
            case .customRange(let start, let end):
                return (start, end)
            }
        }()

        components.queryItems = [
            URLQueryItem(name: "symbol", value: symbol),
            URLQueryItem(name: "table", value: tableName),
            URLQueryItem(name: "start", value: formatter.string(from: startDate)),
            URLQueryItem(name: "end", value: formatter.string(from: endDate))
        ]

        guard let url = components.url else { return [] }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let results = try JSONDecoder().decode([PriceData].self, from: data)
            return results
        } catch {
            print("Network error fetching historical data: \(error)")
            return []
        }
    }

    // 4. 获取财报数据 (Async)
    func fetchEarningData(forSymbol symbol: String) async -> [EarningData] {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/earning") else { return [] }
        components.queryItems = [URLQueryItem(name: "symbol", value: symbol)]

        guard let url = components.url else { return [] }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let results = try JSONDecoder().decode([EarningData].self, from: data)
            return results
        } catch {
            print("Network error fetching earning data: \(error)")
            return []
        }
    }

    // 5. 获取收盘价 (Async)
    func fetchClosingPrice(forSymbol symbol: String, onDate date: Date, tableName: String) async -> Double? {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/closing_price") else { return nil }

        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"

        components.queryItems = [
            URLQueryItem(name: "symbol", value: symbol),
            URLQueryItem(name: "date", value: formatter.string(from: date)),
            URLQueryItem(name: "table", value: tableName)
        ]

        guard let url = components.url else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let response = try JSONDecoder().decode([String: Double?].self, from: data)
            return response["price"] ?? nil
        } catch {
            print("Network error fetching closing price: \(error)")
            return nil
        }
    }

    // 6. 检查表是否有 Volume (Async - 实际逻辑在服务器端处理，这里仅保留接口或简化)
    // 由于服务器端的 query_historical 会自动处理 volume 字段，
    // 客户端其实不需要显式检查。为了兼容旧代码调用，可以返回 true (假设服务器处理) 或移除调用。
    // 这里我们简单返回 true，因为服务器 API 已经封装了 schema 检查。
    func checkIfTableHasVolume(tableName: String) async -> Bool {
        return true 
    }

    // 7. 获取期权汇总数据 (Async) - 新增
    func fetchOptionsSummary(forSymbol symbol: String) async -> OptionsSummary? {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/options_summary") else { return nil }
        components.queryItems = [URLQueryItem(name: "symbol", value: symbol)]

        guard let url = components.url else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let result = try JSONDecoder().decode(OptionsSummary.self, from: data)
            return result
        } catch {
            print("Network error fetching options summary: \(error)")
            return nil
        }
    }

    // 8. 获取期权历史价格数据 (Async) - 新增
    func fetchOptionsHistory(forSymbol symbol: String) async -> [OptionHistoryItem] {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/options_price_history") else { return [] }
        components.queryItems = [URLQueryItem(name: "symbol", value: symbol)]

        guard let url = components.url else { return [] }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let results = try JSONDecoder().decode([OptionHistoryItem].self, from: data)
            return results
        } catch {
            print("Network error fetching options history: \(error)")
            return []
        }
    }
}

import SwiftUI
import Charts
import Foundation

// MARK: - 【重构】期权价格历史图表组件
struct OptionsHistoryChartView: View {
    let symbol: String

    // 状态管理
    @State private var historyData: [DatabaseManager.OptionHistoryItem] = []
    @State private var selectedTimeRange: TimeRangeOption = .threeMonths
    @State private var isLoading = false

    // 定义时间范围枚举
    enum TimeRangeOption: String, CaseIterable, Identifiable {
        case threeMonths = "3M"
        case sixMonths = "6M"
        case oneYear = "1Y"
        case twoYears = "2Y"
        case fiveYears = "5Y"
        case tenYears = "10Y"

        var id: String { self.rawValue }

        var monthsBack: Int {
            switch self {
            case .threeMonths: return 3
            case .sixMonths: return 6
            case .oneYear: return 12
            case .twoYears: return 24
            case .fiveYears: return 60
            case .tenYears: return 120
            }
        }
    }

    // 过滤后的数据
    var filteredData: [DatabaseManager.OptionHistoryItem] {
        let calendar = Calendar.current
        guard let startDate = calendar.date(byAdding: .month, value: -selectedTimeRange.monthsBack, to: Date()) else {
            return historyData
        }
        return historyData.filter { $0.date >= startDate }
    }

    var body: some View {
        VStack(spacing: 12) {
            // 1. 图表主体区域
            mainChartArea

            // 2. 时间切换条
            timeRangeSelector
        }
        .task {
            await loadData()
        }
    }

    // 拆分出图表主体
    @ViewBuilder
    private var mainChartArea: some View {
        ZStack {
            RoundedRectangle(cornerRadius: 16)
                .fill(Color(UIColor.secondarySystemGroupedBackground))
                .shadow(color: Color.black.opacity(0.05), radius: 5, x: 0, y: 2)

            if isLoading {
                ProgressView()
            } else if historyData.isEmpty {
                Text("暂无历史价格数据")
                    .font(.caption)
                    .foregroundColor(.secondary)
            } else if filteredData.isEmpty {
                Text("该时间段内无数据")
                    .font(.caption)
                    .foregroundColor(.secondary)
            } else {
                chartContent
            }
        }
        .frame(height: 220)
        .padding(.horizontal)
    }

    // 拆分出具体的 Chart 代码
    private var chartContent: some View {
        Chart {
            ForEach(filteredData) { item in
                BarMark(
                    x: .value("Date", item.date),
                    y: .value("Price", item.price)
                )
                // 【注意】移除了 .width 修饰符以解决 "has no member width" 报错。
                // Charts 会自动根据数据密度调整柱子宽度。
                .foregroundStyle(barGradient(for: item.price))
            }

            // 0轴基准线
            RuleMark(y: .value("Zero", 0))
                .lineStyle(StrokeStyle(lineWidth: 1, dash: [5]))
                .foregroundStyle(.gray.opacity(0.5))
        }
        .chartYAxis {
            AxisMarks(position: .leading)
        }
        .chartXAxis {
            AxisMarks(values: .automatic) { value in
                AxisGridLine()
                AxisTick()
                if let date = value.as(Date.self) {
                    AxisValueLabel {
                        Text(date, format: .dateTime.month().year(.twoDigits))
                            .font(.caption2)
                    }
                }
            }
        }
        .padding(.vertical, 16)
        .padding(.horizontal, 8)
    }

    // 辅助函数：生成渐变色
    private func barGradient(for price: Double) -> LinearGradient {
        let isPositive = price >= 0
        let colors: [Color] = isPositive
            ? [.red.opacity(0.8), .red.opacity(0.4)]
            : [.green.opacity(0.8), .green.opacity(0.4)]

        return LinearGradient(
            colors: colors,
            startPoint: isPositive ? .bottom : .top,
            endPoint: isPositive ? .top : .bottom
        )
    }

    // 拆分出时间选择器
    private var timeRangeSelector: some View {
        HStack(spacing: 0) {
            ForEach(TimeRangeOption.allCases) { option in
                Button(action: {
                    withAnimation(.easeInOut) {
                        selectedTimeRange = option
                    }
                }) {
                    Text(option.rawValue)
                        .font(.system(size: 13, weight: .medium))
                        .frame(maxWidth: .infinity)
                        .padding(.vertical, 8)
                        .background(
                            selectedTimeRange == option
                            ? Color.blue.opacity(0.15)
                            : Color.clear
                        )
                        .foregroundColor(
                            selectedTimeRange == option
                            ? .blue
                            : .secondary
                        )
                        .clipShape(RoundedRectangle(cornerRadius: 8))
                }
            }
        }
        .padding(4)
        .background(Color(UIColor.tertiarySystemFill))
        .cornerRadius(10)
        .padding(.horizontal)
    }

    private func loadData() async {
        isLoading = true
        let rawData = await DatabaseManager.shared.fetchOptionsHistory(forSymbol: symbol)
        await MainActor.run {
            self.historyData = rawData
            self.isLoading = false
        }
    }
}

// MARK: - 【重构】界面 A：期权 Symbol 列表
struct OptionsListView: View {
    @EnvironmentObject var dataService: DataService
    @EnvironmentObject var authManager: AuthManager
    @EnvironmentObject var usageManager: UsageManager

    @State private var selectedSymbol: String?
    @State private var navigateToDetail = false
    @State private var showSubscriptionSheet = false

    // 【新增】控制跳转到榜单页面
    @State private var navigateToRank = false

    var sortedSymbols: [String] {
        let allSymbols = dataService.optionsData.keys
        let noCapSymbols = allSymbols.filter { symbol in
            guard let item = dataService.marketCapData[symbol.uppercased()] else { return true }
            return item.rawMarketCap <= 0
        }.sorted()

        let hasCapSymbols = allSymbols.filter { symbol in
            guard let item = dataService.marketCapData[symbol.uppercased()] else { return false }
            return item.rawMarketCap > 0
        }.sorted { s1, s2 in
            let cap1 = dataService.marketCapData[s1.uppercased()]?.rawMarketCap ?? 0
            let cap2 = dataService.marketCapData[s2.uppercased()]?.rawMarketCap ?? 0
            return cap1 > cap2
        }
        return noCapSymbols + hasCapSymbols
    }

    var body: some View {
        List {
            if sortedSymbols.isEmpty {
                Text("暂无期权异动数据")
                    .foregroundColor(.secondary)
            } else {
                ForEach(sortedSymbols, id: \.self) { symbol in
                    OptionListRow(symbol: symbol) {
                        handleSelection(symbol)
                    }
                }
            }
        }
        .navigationTitle("期权异动")
        .navigationBarTitleDisplayMode(.inline)
        // 【新增】右上角按钮
        .toolbar {
            ToolbarItem(placement: .navigationBarTrailing) {
                Button(action: {
                    // 这里原来是 .openSpecialList，改为 .viewOptionsRank
                    if usageManager.canProceed(authManager: authManager, action: .viewOptionsRank) { 
                        self.navigateToRank = true
                    } else {
                        self.showSubscriptionSheet = true
                    }
                }) {
                    // 【修改点】设计漂亮的胶囊按钮
                    HStack(spacing: 4) {
                        // 加个小图标增加精致感
                        Image(systemName: "chart.line.uptrend.xyaxis")
                            .font(.system(size: 12, weight: .bold))

                        Text("涨跌预测榜")
                            .font(.system(size: 13, weight: .bold))
                    }
                    .padding(.vertical, 6)
                    .padding(.horizontal, 12)
                    .foregroundColor(.white)
                    .background(
                        // 蓝紫色渐变，体现“预测/智能”的感觉
                        LinearGradient(
                            gradient: Gradient(colors: [Color.blue, Color.indigo]),
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                    )
                    .clipShape(Capsule()) // 胶囊圆角
                    .shadow(color: Color.blue.opacity(0.3), radius: 4, x: 0, y: 2) // 柔和阴影
                    .overlay(
                        // 增加一道淡淡的高光描边，增加立体感
                        Capsule()
                            .stroke(Color.white.opacity(0.2), lineWidth: 1)
                    )
                }
            }
        }
        .navigationDestination(isPresented: $navigateToDetail) {
            if let sym = selectedSymbol {
                OptionsDetailView(symbol: sym)
            }
        }
        // 【新增】跳转目的地
        .navigationDestination(isPresented: $navigateToRank) {
            OptionsRankView()
        }
        .sheet(isPresented: $showSubscriptionSheet) { SubscriptionView() }
    }

    private func handleSelection(_ symbol: String) {
        if usageManager.canProceed(authManager: authManager, action: .viewOptionsDetail) {
            self.selectedSymbol = symbol
            self.navigateToDetail = true
        } else {
            self.showSubscriptionSheet = true
        }
    }
}

// 拆分出的列表行视图
struct OptionListRow: View {
    let symbol: String
    let action: () -> Void
    @EnvironmentObject var dataService: DataService
    // --- 新增：用于存储最新价格的状态 ---
    @State private var latestPrice: Double? = nil

    var body: some View {
        Button(action: action) {
            let info = getInfo(for: symbol)
            HStack {
                VStack(alignment: .leading, spacing: 4) {
                    HStack(spacing: 8) {
                        Text(symbol)
                            .font(.headline)
                            .fontWeight(.bold)
                            // --- 修改点：根据最新价格上色 ---
                            .foregroundColor(priceColor)

                        if !info.name.isEmpty {
                            Text(info.name)
                                .font(.subheadline)
                                .foregroundColor(.secondary)
                                .lineLimit(1)
                                .truncationMode(.tail)
                        }
                    }

                    if !info.tags.isEmpty {
                        Text(info.tags.joined(separator: ", "))
                            .font(.caption)
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                            .truncationMode(.tail)
                    }
                }
                Spacer()
                Image(systemName: "chevron.right")
                    .font(.caption)
                    .foregroundColor(.gray)
            }
            .padding(.vertical, 4)
        }
        // --- 新增：组件加载时请求历史数据获取最新价格 ---
        .task {
            await loadLatestPrice()
        }
    }

    // --- 新增：计算属性确定颜色 ---
    private var priceColor: Color {
        guard let price = latestPrice else { return .primary } // 数据未加载时用默认色
        return price >= 0 ? .red : .green // 正数为红，负数为绿
    }

    // --- 新增：加载数据的逻辑 ---
    private func loadLatestPrice() async {
        let history = await DatabaseManager.shared.fetchOptionsHistory(forSymbol: symbol)
        // 假设 history[0] 是最新一天的价格（根据 API 返回顺序确定）
        if let latestItem = history.first {
            await MainActor.run {
                self.latestPrice = latestItem.price
            }
        }
    }

    private func getInfo(for symbol: String) -> (name: String, tags: [String]) {
        let upperSymbol = symbol.uppercased()
        if let stock = dataService.descriptionData?.stocks.first(where: { $0.symbol.uppercased() == upperSymbol }) {
            return (stock.name, stock.tag)
        }
        if let etf = dataService.descriptionData?.etfs.first(where: { $0.symbol.uppercased() == upperSymbol }) {
            return (etf.name, etf.tag)
        }
        return ("", [])
    }
}

// MARK: - 【重构】界面 B：期权详情表格
struct OptionsDetailView: View {
    let symbol: String
    @EnvironmentObject var dataService: DataService

    // --- 新增：注入权限和点数管理对象 ---
    @EnvironmentObject var authManager: AuthManager
    @EnvironmentObject var usageManager: UsageManager

    @State private var selectedTypeIndex = 0
    @State private var navigateToChart = false
    @State private var summaryCall: String = ""
    @State private var summaryPut: String = ""

    // --- 新增：控制订阅页显示 ---
    @State private var showSubscriptionSheet = false

    var filteredData: [OptionItem] {
        guard let items = dataService.optionsData[symbol] else { return [] }
        let filtered = items.filter { item in
            let itemType = item.type.uppercased()
            if selectedTypeIndex == 0 {
                return itemType.contains("CALL") || itemType == "C"
            } else {
                return itemType.contains("PUT") || itemType == "P"
            }
        }
        return filtered.sorted { item1, item2 in
            let val1 = Double(item1.change) ?? 0
            let val2 = Double(item2.change) ?? 0
            return abs(val1) > abs(val2)
        }
    }

    var body: some View {
        VStack(spacing: 0) {
            // 图表组件
            OptionsHistoryChartView(symbol: symbol)
                .padding(.top, 10)
                .padding(.bottom, 4)

            // 顶部切换开关 (Picker)
            typePickerView

            // 表格头
            tableHeaderView

            Divider()

            // 数据列表
            dataListView
        }
        .navigationTitle(displayTitle) // 使用我们拼接好的字符串
        .navigationBarTitleDisplayMode(.inline)
        .background(Color(UIColor.systemGroupedBackground))
        .toolbar {
            ToolbarItem(placement: .navigationBarTrailing) {
                // --- 修改点：在按钮点击时执行扣点检查 ---
                Button(action: {
                    if usageManager.canProceed(authManager: authManager, action: .viewChart) { 
                        // 如果有足够点数（或已订阅），则允许跳转
                        navigateToChart = true 
                    } else {
                        // 点数不足，弹出订阅/登录页
                        showSubscriptionSheet = true
                    }
                }) {
                    Text("切换股价模式")
                        .font(.system(size: 13, weight: .bold))
                        .foregroundColor(.white)
                        .padding(.horizontal, 10)
                        .padding(.vertical, 5)
                        .background(Color.blue)
                        .cornerRadius(14)
                        .shadow(color: Color.blue.opacity(0.3), radius: 2, x: 0, y: 1)
                }
            }
        }
        .navigationDestination(isPresented: $navigateToChart) {
            let groupName = dataService.getCategory(for: symbol) ?? "US"
            ChartView(symbol: symbol, groupName: groupName)
        }
        // --- 新增：挂载订阅页面 ---
        .sheet(isPresented: $showSubscriptionSheet) { SubscriptionView() }
        .task {
            // 获取汇总数据
            if let summary = await DatabaseManager.shared.fetchOptionsSummary(forSymbol: symbol) {
                await MainActor.run {
                    if let c = summary.call { self.summaryCall = c }
                    if let p = summary.put { self.summaryPut = p }
                }
            }
        }
    }

    // MARK: - 辅助逻辑
    private var displayTitle: String {
        // 1. 获取原始的 compare 字符串 (例如 "0.04%++")
        if let compareStr = dataService.compareDataUppercased[symbol.uppercased()] {
            // 2. 提取百分比部分
            let pattern = "([+-]?\\d+(\\.\\d+)?%)"
            if let range = compareStr.range(of: pattern, options: .regularExpression) {
                let percentage = String(compareStr[range])
                // 3. 返回拼接后的格式：NVDA (0.04%)
                return "\(symbol) (\(percentage))"
            }
        }
        // 如果找不到数据，则只显示 Symbol
        return symbol
    }

    // 拆分出 Picker
    private var typePickerView: some View {
        Picker("Type", selection: $selectedTypeIndex) {
            Text(summaryCall.isEmpty ? "Calls" : "Calls \(summaryCall)").tag(0)
            Text(summaryPut.isEmpty ? "Puts" : "Puts \(summaryPut)").tag(1)
        }
        .pickerStyle(SegmentedPickerStyle())
        .padding()
        .background(Color(UIColor.systemBackground))
    }

    // 拆分出表头
    private var tableHeaderView: some View {
        HStack(spacing: 4) {
            Text("Expiry").frame(maxWidth: .infinity, alignment: .leading)
            Text("Strike").frame(width: 55, alignment: .trailing)
            Text("Dist").frame(width: 55, alignment: .trailing)
            Text("Open Int").frame(width: 65, alignment: .trailing)
            Text("1-Day").frame(width: 60, alignment: .trailing)
        }
        .font(.caption)
        .foregroundColor(.secondary)
        .padding(.horizontal)
        .padding(.bottom, 8)
        .background(Color(UIColor.systemBackground))
    }

    // 拆分出列表部分
    private var dataListView: some View {
        ScrollViewReader { proxy in
            ScrollView {
                LazyVStack(spacing: 0) {
                    Color.clear.frame(height: 0).id("TopAnchor")

                    if filteredData.isEmpty {
                        Text("暂无数据")
                            .foregroundColor(.secondary)
                            .padding(.top, 20)
                    } else {
                        ForEach(filteredData) { item in
                            OptionRowView(item: item)
                            Divider().padding(.leading)
                        }
                    }
                }
            }
            .onChange(of: selectedTypeIndex) { _, _ in
                proxy.scrollTo("TopAnchor", anchor: .top)
            }
        }
    }
}

