    lines = output.split('\n')
    for line in lines:
        if line.strip():
            # 格式兼容: category symbol descriptor [price...]
            parts = line.split()
            if len(parts) >= 2:
                category = parts[0]
                symbol = parts[1]
                if category in updates:
                    updates[category].append(symbol)
                else:
                    updates[category] = [symbol]
    return updates

