def get_price_comparison_mode(cursor, table_name, interval, name, validate, mode='month'):
    """
    Logic A: 对应 a.py 的 get_price_comparison
    """
    ex_validate = validate - timedelta(days=1)

    if mode == 'month':
        today = datetime.now()
        past_date = today - relativedelta(months=int(interval))
    elif mode == 'week':
        past_date = validate - timedelta(weeks=interval)
    else:
        raise ValueError("Unknown mode for get_price_comparison")

    query = f"""
    SELECT MAX(price), MIN(price)
    FROM {table_name} WHERE date BETWEEN ? AND ? AND name = ?
    """
    cursor.execute(query, (past_date.strftime("%Y-%m-%d"), ex_validate.strftime("%Y-%m-%d"), name))
    result = cursor.fetchone()

    if result and (result[0] is not None and result[1] is not None):
        return result
    else:
        return None

def parse_output_color_wm(output):
    """
    Logic A: 解析 W (周) 和 M (月) 标签
    """
    updates_color = {}
    lines = output.split('\n')
    for line in lines:
        if not line.strip(): continue
        parts = line.split()
        if len(parts) < 3: continue

        symbol = parts[1]
        descriptor = parts[2]
        category_list = None

        if 'W' in descriptor:
            week_part, _ = descriptor.split('_')
            if 'W' in week_part:
                try:
                    weeks = int(week_part.replace('W', ''))
                    if weeks in [6, 8, 10]:
                        category_list = 'blue_keywords'
                except ValueError:
                    continue

        elif 'M' in descriptor:
            year_part, _ = descriptor.split('_')
            if 'Y' in year_part: continue 
            if 'M' in year_part:
                try:
                    months = int(year_part.replace('M', ''))
                    if months == 5:
                        category_list = 'cyan_keywords'
                except ValueError:
                    continue

        if category_list:
            if category_list in updates_color:
                if symbol not in updates_color[category_list]:
                    updates_color[category_list].append(symbol)
            else:
                updates_color[category_list] = [symbol]
    return updates_color

def update_color_json_priority(color_config_path, updates_colors):
    """Logic A: 带优先级的颜色更新"""
    color_priority = {
        'black_keywords': 1,
        'orange_keywords': 2,
        'yellow_keywords': 3,
        'white_keywords': 4,
        'blue_keywords': 5,
        'cyan_keywords': 5
    }
    with open(color_config_path, 'r', encoding='utf-8') as file:
        all_colors = json.load(file)
    colors = {k: v for k, v in all_colors.items() if k != "red_keywords"}

    symbol_to_color = {}
    for color, symbols in colors.items():
        for symbol in symbols:
            symbol_to_color[symbol] = color

    for category_list, names in updates_colors.items():
        if category_list not in color_priority:
            continue
        new_priority = color_priority[category_list]
        for name in names:
            existing_color = symbol_to_color.get(name)
            if existing_color:
                existing_priority = color_priority.get(existing_color, float('inf'))
                if new_priority <= existing_priority:
                    if name in colors[existing_color]:
                        colors[existing_color].remove(name)
                        if not colors[existing_color]:
                            del colors[existing_color]

                    if category_list in colors:
                        colors[category_list].append(name)
                    else:
                        colors[category_list] = [name]
                    symbol_to_color[name] = category_list
                    print(f"[Logic A] Symbol {name} 从 {existing_color} 移动到 {category_list}。")
                else:
                    print(f"[Logic A] Symbol {name} 已在 {existing_color} 中，优先级跳过。")
            else:
                if category_list in colors:
                    colors[category_list].append(name)
                else:
                    colors[category_list] = [name]
                symbol_to_color[name] = category_list
                print(f"[Logic A] Symbol {name} 添加到 {category_list}。")

    colors["red_keywords"] = all_colors.get("red_keywords", [])
    with open(color_config_path, 'w', encoding='utf-8') as file:
        json.dump(colors, file, ensure_ascii=False, indent=4)

