def get_latest_price_and_date(cursor, table_name, name):
    """获取指定股票的最新价格和日期"""
    query = f"SELECT date, price FROM {table_name} WHERE name = ? ORDER BY date DESC LIMIT 1"
    cursor.execute(query, (name,))
    return cursor.fetchone()

# ================= 核心逻辑函数 (合并版) =================

def get_price_comparison(cursor, table_name, interval, name, validate, mode='month'):
    """
    获取价格比较数据
    mode='month': 对应 Analyse_Stocks_500 的逻辑 (使用 months, 起始日期基于 today)
    mode='week':  对应 Analyse_Stocks_5000 的逻辑 (使用 weeks, 起始日期基于 validate)
    """
    ex_validate = validate - timedelta(days=1)

    if mode == 'month':
        # 500脚本逻辑：基于当前时间往前推月数
        today = datetime.now()
        past_date = today - relativedelta(months=int(interval))
    elif mode == 'week':
        # 5000脚本逻辑：基于数据有效日期往前推周数
        past_date = validate - timedelta(weeks=interval)
    else:
        raise ValueError("Unknown mode for get_price_comparison")

    query = f"""
    SELECT MAX(price), MIN(price)
    FROM {table_name} WHERE date BETWEEN ? AND ? AND name = ?
    """
    cursor.execute(query, (past_date.strftime("%Y-%m-%d"), ex_validate.strftime("%Y-%m-%d"), name))
    result = cursor.fetchone()

    if result and (result[0] is not None and result[1] is not None):
        return result
    else:
        return None

def parse_output(output):
    """解析输出文本，构建用于更新 Sectors_panel.json 的数据"""
    updates = {}
    lines = output.split('\n')
    for line in lines:
        if line.strip():
            # 格式: category symbol descriptor
            parts = line.split()
            if len(parts) >= 2:
                category = parts[0]
                symbol = parts[1]
                if category in updates:
                    updates[category].append(symbol)
                else:
                    updates[category] = [symbol]
    return updates

def parse_output_color(output):
    """
    解析输出文本，构建用于更新 Colors.json 的数据。
    同时处理 'W' (5000脚本/蓝色) 和 'M' (500脚本/青色) 的标签。
    """
    updates_color = {}
    lines = output.split('\n')
    for line in lines:
        if not line.strip():
            continue

        parts = line.split()
        if len(parts) < 3:
            continue

        symbol = parts[1]
        descriptor = parts[2]  # 例如 '10W_newlow' 或 '5M_newlow'

        category_list = None

        # 解析逻辑
        if 'W' in descriptor: # 处理周 (5000逻辑)
            week_part, _ = descriptor.split('_')
            if 'W' in week_part:
                try:
                    weeks = int(week_part.replace('W', ''))
                    if weeks in [6, 8, 10]:
                        category_list = 'blue_keywords'
                except ValueError:
                    continue

        elif 'M' in descriptor: # 处理月 (500逻辑)
            year_part, _ = descriptor.split('_')
            if 'Y' in year_part: continue # 忽略年
            if 'M' in year_part:
                try:
                    months = int(year_part.replace('M', ''))
                    if months == 5:
                        category_list = 'cyan_keywords'
                except ValueError:
                    continue

        # 如果匹配到了颜色类别，添加到更新列表
        if category_list:
            if category_list in updates_color:
                if symbol not in updates_color[category_list]:
                    updates_color[category_list].append(symbol)
            else:
                updates_color[category_list] = [symbol]

    return updates_color

def update_json_data(config_path, updates, blacklist_newlow):
    """更新 Sectors_panel.json"""
    with open(config_path, 'r', encoding='utf-8') as file:
        data = json.load(file, object_pairs_hook=OrderedDict)

    for category, symbols in updates.items():
        if category in data:
            for symbol in symbols:
                if symbol not in data[category] and symbol not in blacklist_newlow:
                    data[category][symbol] = ""
                    print(f"将symbol '{symbol}' 添加到Panel文件的类别 '{category}' 中")
                elif symbol in data[category]:
                    print(f"'{symbol}' 已存在于Panel文件的类别 '{category}' 中，跳过")
                else:
                    print(f"'{symbol}' 在黑名单中，跳过")
        else:
            data[category] = {symbol: "" for symbol in symbols if symbol not in blacklist_newlow}

    with open(config_path, 'w', encoding='utf-8') as file:
        json.dump(data, file, ensure_ascii=False, indent=4)

def update_color_json(color_config_path, updates_colors):
    """更新 Colors.json，包含合并的优先级逻辑"""
    # 合并后的优先级
    color_priority = {
        'black_keywords': 1,
        'orange_keywords': 2,
        'yellow_keywords': 3,
        'white_keywords': 4,
        'blue_keywords': 5,  # 5000 Script
        'cyan_keywords': 5   # 500 Script
    }

    with open(color_config_path, 'r', encoding='utf-8') as file:
        all_colors = json.load(file)

    # 排除 "red_keywords"
    colors = {k: v for k, v in all_colors.items() if k != "red_keywords"}

    # 构建 symbol -> color 映射
    symbol_to_color = {}
    for color, symbols in colors.items():
        for symbol in symbols:
            symbol_to_color[symbol] = color

    for category_list, names in updates_colors.items():
        if category_list not in color_priority:
            log_and_print_error(f"未知的颜色类别: {category_list}, 跳过。")
            continue

        new_priority = color_priority[category_list]

        for name in names:
            existing_color = symbol_to_color.get(name)
            if existing_color:
                existing_priority = color_priority.get(existing_color, float('inf'))

                # 如果新颜色优先级更高（数值更小），则更新
                if new_priority <= existing_priority:
                    if name in colors[existing_color]:
                        colors[existing_color].remove(name)
                        if not colors[existing_color]:
                            del colors[existing_color]

                    if category_list in colors:
                        colors[category_list].append(name)
                    else:
                        colors[category_list] = [name]

                    symbol_to_color[name] = category_list
                    print(f"Symbol {name} 从 {existing_color} 移动到 {category_list}。")
                else:
                    # 优先级相同或更低，跳过 (注意：这意味着如果5000先运行标记为蓝色，500运行时如果是青色，优先级相同，将不会覆盖蓝色)
                    print(f"Symbol {name} 已在 {existing_color} 中，优先级跳过。")
            else:
                # 新增
                if category_list in colors:
                    colors[category_list].append(name)
                else:
                    colors[category_list] = [name]
                symbol_to_color[name] = category_list
                print(f"Symbol {name} 添加到 {category_list}。")

    # 加回 red_keywords
    colors["red_keywords"] = all_colors.get("red_keywords", [])

    try:
        with open(color_config_path, 'w', encoding='utf-8') as file:
            json.dump(colors, file, ensure_ascii=False, indent=4)
    except Exception as e:
        log_and_print_error(f"写入Colors文件时发生错误: {e}")

