def get_price_comparison_days(cursor, table_name, interval, name, validate):
    """Logic B: 对应 b.py 的 get_price_comparison (支持 <1 的 interval 转换为天)"""
    today = datetime.now()
    ex_validate = validate - timedelta(days=1)

    if interval < 1:
        days = int(interval * 30)
        past_date = validate - timedelta(days=days - 1)
    else:
        past_date = today - relativedelta(months=int(interval))

    query = f"""
    SELECT MAX(price), MIN(price)
    FROM {table_name} WHERE date BETWEEN ? AND ? AND name = ?
    """
    cursor.execute(query, (past_date.strftime("%Y-%m-%d"), ex_validate.strftime("%Y-%m-%d"), name))
    result = cursor.fetchone()
    if result and (result[0] is not None and result[1] is not None):
        return result
    else:
        return None

def parse_output_color_y(output):
    """Logic B: 仅处理 Y (年) 标签，忽略 M"""
    updates_color = {}
    lines = output.split('\n')
    for line in lines:
        if line.strip():
            parts = line.split()
            if len(parts) < 3: continue
            symbol = parts[1]
            descriptor = parts[2]

            year_part, _ = descriptor.split('_')
            if 'M' in year_part: continue
            if 'Y' in year_part:
                try:
                    years = int(year_part.replace('Y', ''))
                    category_list = None
                    if years == 1: category_list = 'white_keywords'
                    elif years == 2: category_list = 'yellow_keywords'
                    elif years == 5: category_list = 'orange_keywords'
                    elif years == 10: category_list = 'black_keywords'

                    if category_list:
                        if category_list in updates_color:
                            if symbol not in updates_color[category_list]:
                                updates_color[category_list].append(symbol)
                        else:
                            updates_color[category_list] = [symbol]
                except ValueError:
                    continue
    return updates_color

def update_color_json_exclusive(color_config_path, updates_colors):
    """Logic B: 排他性更新 (移除旧颜色，应用新颜色)"""
    try:
        with open(color_config_path, 'r', encoding='utf-8') as file:
            all_colors = json.load(file)
    except Exception as e:
        print(f"读取Colors文件错误: {e}")
        return

    colors = {k: v for k, v in all_colors.items() if k != "red_keywords"}

    for category_list, names in updates_colors.items():
        for name in names:
            moved = False
            for key in colors:
                if name in colors[key]:
                    if key != category_list:
                        colors[key].remove(name)
                        print(f"[Logic B] 将 '{name}' 从 '{key}' 类别中移除")
                        moved = True
                    break

            if category_list not in colors:
                colors[category_list] = []

            if name not in colors[category_list]:
                colors[category_list].append(name)
                print(f"[Logic B] 将 '{name}' 添加到 '{category_list}' 类别中")
            elif not moved:
                print(f"[Logic B] '{name}' 已经在 '{category_list}' 类别中")

    colors["red_keywords"] = all_colors.get("red_keywords", [])
    try:
        with open(color_config_path, 'w', encoding='utf-8') as file:
            json.dump(colors, file, ensure_ascii=False, indent=4)
    except Exception as e:
        print(f"写入Colors文件错误: {e}")

def load_existing_highs_json(file_path):
    highs_map = {}
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        if 'stocks' in data and isinstance(data.get('stocks'), list):
            for stock_group in data['stocks']:
                if isinstance(stock_group, dict):
                    for symbol, price_str in stock_group.items():
                        try:
                            highs_map[symbol] = float(price_str)
                        except (ValueError, TypeError):
                            pass
    except Exception:
        return {}
    return highs_map

def clean_old_backups(directory, file_patterns):
    if not os.path.exists(directory): return
    now = datetime.now()
    for filename in os.listdir(directory):
        for prefix, date_position, retention_days in file_patterns:
            if filename.startswith(prefix):
                try:
                    cutoff = now.replace(hour=0, minute=0, second=0, microsecond=0) - timedelta(days=retention_days)
                    parts = filename.split('_')
                    # 这里假设日期总是在文件名末尾或者指定位置，且格式为 yymmdd.txt 或 similar
                    # B脚本原始逻辑是：parts[date_position].split('.')[0][-6:]
                    date_part = parts[date_position]
                    if '.' in date_part:
                        date_str = date_part.split('.')[0][-6:]
                    else:
                        date_str = date_part[-6:]

                    file_date = datetime.strptime(date_str, '%y%m%d')
                    file_date = file_date.replace(hour=0, minute=0, second=0, microsecond=0)

                    if file_date < cutoff:
                        file_path = os.path.join(directory, filename)
                        os.remove(file_path)
                        print(f"删除旧备份文件：{file_path}")
                    break
                except Exception:
                    pass

def read_compare_all(file_path):
