    return compare_data

def load_descriptions_and_create_tag_map(file_path):
    tag_map = {}
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        for item in data.get('stocks', []):
            symbol = item.get('symbol')
            tags = item.get('tag', [])
            if symbol and tags:
                tag_map[symbol] = ','.join(tags)
        for item in data.get('etfs', []):
            symbol = item.get('symbol')
            tags = item.get('tag', [])
            if symbol and tags:
                tag_map[symbol] = ','.join(tags)
    except Exception as e:
        print(f"读取description.json错误: {e}")
    return tag_map

def process_high_data(input_lines, compare_data, tag_map):
    processed_lines = []
    for line in input_lines:
        parts = line.split()
        new_line = ""
        symbol = ""
        if len(parts) >= 4:
            sector = parts[0]
            symbol = parts[1]
            price_str = parts[-1]
            compare_info = compare_data.get(symbol, '')
            if compare_info:
                new_line = f"{sector} {symbol} {compare_info} {price_str}"
            else:
                new_line = f"{sector} {symbol} {price_str}"
        elif len(parts) >= 3:
            sector = parts[0]
            symbol = parts[1]
            compare_info = compare_data.get(symbol, '')
            if compare_info:
                new_line = f"{sector} {symbol} {compare_info}"
            else:
                new_line = f"{sector} {symbol}"

        if new_line and symbol:
            tags_string = tag_map.get(symbol, '')
            if tags_string:
                final_line = f"{new_line} {tags_string}"
            else:
                final_line = new_line
            processed_lines.append(final_line)
    return processed_lines

