                # 如果这个区间里只有最新一条（或根本没有）数据，就跳过，不当高低点
                if len(prices_in_interval) < 2:
                    continue
                # =======================

                min_price_in_interval = min(prices_in_interval)
                max_price_in_interval = max(prices_in_interval)

                if latest_price == min_price_in_interval:
