def main():    
    db_path = '/Users/yanzhang/Coding/Database/Finance.db'
    blacklist_path = '/Users/yanzhang/Coding/Financial_System/Modules/blacklist.json'
    blacklist_newlow = load_blacklist_newlow(blacklist_path)

