    // Key 是 Symbol (大写), Value 是该 Symbol 下所有的期权条目
    @Published var optionsData: [String: [OptionItem]] = [:]

    private var isDataLoaded = false
    private var isInitialLoad: Bool {
        let localVersion = UserDefaults.standard.string(forKey: "FinanceAppLocalDataVersion")
        return localVersion == nil || localVersion == "0.0"
    }

    // 【新增】更新阀值的方法
    func updateOptionCapLimit(_ limit: Double) {
        DispatchQueue.main.async {
            self.optionCapLimit = limit
        }
    }

    // 【新增】获取期权榜单数据 (Async)
    // 返回元组: (上涨列表, 下跌列表)
    func fetchOptionsRankData() async -> ([OptionRankItem], [OptionRankItem])? {
        // 使用配置的阀值
        let urlString = "\(DatabaseManager.shared.serverBaseURL)/query/options_rank?limit=\(String(format: "%.0f", optionCapLimit))"
        guard let url = URL(string: urlString) else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let result = try JSONDecoder().decode(OptionRankResponse.self, from: data)
            return (result.rank_up, result.rank_down)
        } catch {
            print("DataService: 获取期权榜单失败: \(error)")
            return nil
        }
    }

    // MARK: - 【修改点 5】新增：更新策略组配置的方法
    func updateStrategyConfig(groups: [String], names: [String: String]) {
        DispatchQueue.main.async {
            self.strategyGroupNames = Set(groups)
            self.orderedStrategyGroups = groups // <--- 【修改 3：更新时保存顺序】
            self.groupDisplayMap = names
        }
        UserDefaults.standard.set(groups, forKey: strategyGroupsKey)
        UserDefaults.standard.set(names, forKey: groupNamesKey)
    }

    // 【新增】更新时间戳并持久化
    func updateTimestamps(eco: String?, intro: String?) {
        DispatchQueue.main.async {
            self.ecoDataTimestamp = eco
            self.introSymbolTimestamp = intro
        }

        if let eco = eco {
            UserDefaults.standard.set(eco, forKey: ecoDataKey)
        }
        if let intro = intro {
            UserDefaults.standard.set(intro, forKey: introSymbolKey)
        }
    }

    // 兼容之前的调用名（可选）
    func updateStrategyGroups(_ groups: [String]) {
        self.updateStrategyConfig(groups: groups, names: self.groupDisplayMap)
    }

    // 【核心修改】：将 loadData 改为异步触发，不阻塞主线程
    func loadData() {
        // 【修改】同时检查 是否已加载 和 是否正在加载
        guard !isDataLoaded, !isLoading else {
            print("DataService: 数据已加载或正在加载中，跳过重复请求。")
            return
        }

        // 标记开始加载
        self.isLoading = true

        DispatchQueue.main.async { self.errorMessage = nil }

        Task.detached(priority: .userInitiated) {
            print("DataService: 开始在后台加载数据...")

            // 1. 并行或串行加载本地文件 (IO操作)
            // 注意：这里调用的是同步方法，但在 detached Task 中运行，不会卡 UI
            await self.loadDescriptionPair()
            await self.loadSectorsData()
            await self.loadCompareDataPair()
            await self.loadSectorsPanel()
            await self.loadEarningRelease()
            await self.loadHighLowData()
            await self.loadCompareStock()
            await self.loadTagsWeight()
            await self.loadCompareETFs()
            // 【新增】加载 10年新高数据
            await self.loadTenYearHighData()
            await self.loadOptionsData() // 加载期权数据

            await MainActor.run {
                self.isDataLoaded = true
                self.isLoading = false // 【新增】加载完成，重置 loading 状态
                print("DataService: 所有本地数据加载完毕 (UI已更新)。")
            }

            // 3. 启动网络请求 (本身就是 async 的)
            await self.loadMarketCapData()
        }
    }

