// 拆分出的列表行视图
struct OptionListRow: View {
    let symbol: String
    let action: () -> Void
    // 【新增】接收长按事件
    let longPressAction: () -> Void

    @EnvironmentObject var dataService: DataService

    // 【修改】Tuple 结构变化：不需要 price 和 prev，只需要 diff 和 iv
    @State private var displayData: (diff: Double, iv: String?)? = nil

    var body: some View {
        // 移除 Button，改用 VStack + 手势
        VStack(alignment: .leading, spacing: 6) {

            // 第一行
            HStack(alignment: .center) {
                // 左侧 Symbol + Name
                HStack(spacing: 6) {
                    Text(symbol)
                        .font(.headline)
                        .fontWeight(.bold)
                        .foregroundColor(.primary)

                    let info = getInfo(for: symbol)
                    if !info.name.isEmpty {
                        Text(info.name)
                            .font(.subheadline)
                            .foregroundColor(.secondary)
                            .lineLimit(1)
                            .truncationMode(.tail)
                    }
                }
                .layoutPriority(0)

                Spacer(minLength: 8)

                // 右侧三联数字
                if let data = displayData {
                    PriceTriView(
                        symbol: symbol,
                        diff: data.diff,
                        iv: data.iv
                    )
                    .layoutPriority(1)
                } else {
                    Text("--")
                        .foregroundColor(.secondary)
                }
                // (小箭头已移除)
            }

            // 第二行 Tags
            let info = getInfo(for: symbol)
            if !info.tags.isEmpty {
                Text(info.tags.joined(separator: ", "))
                    .font(.caption)
                    .foregroundColor(.secondary)
                    .lineLimit(1)
            }
        }
        .padding(.vertical, 4)
        .contentShape(Rectangle()) // 确保点击空白处也能触发
        // 【新增】添加手势
        .onTapGesture {
            action()
        }
        .onLongPressGesture(minimumDuration: 0.5) {
            longPressAction()
        }
        .task {
            await loadPriceAndCalc()
        }
    }

    // 【核心修改】加载数据并执行算法
    // 改为调用 fetchOptionsSummary，直接利用服务器返回的 change 字段
    private func loadPriceAndCalc() async {
        if displayData != nil { return }

        // 调用包含 iv 的新接口
        guard let summary = await DatabaseManager.shared.fetchOptionsSummary(forSymbol: symbol),
              let latest = summary.price,
              let change = summary.change else {
            return
        }

        // 【算法适配】
        // 1. First Value (Diff) = Latest + Change
        let diff = latest + change

        // 3. Third Value (IV)
        let iv = summary.iv

        await MainActor.run {
            self.displayData = (diff, iv)
        }
    }

    private func getInfo(for symbol: String) -> (name: String, tags: [String]) {
        let upperSymbol = symbol.uppercased()
        if let stock = dataService.descriptionData?.stocks.first(where: { $0.symbol.uppercased() == upperSymbol }) {
            return (stock.name, stock.tag)
        }
        if let etf = dataService.descriptionData?.etfs.first(where: { $0.symbol.uppercased() == upperSymbol }) {
            return (etf.name, etf.tag)
        }
        return ("", [])
    }
}

