def parse_output_generic(output):
    """解析 output 文本，提取 {category: [symbols]}"""
    updates = {}
    lines = output.split('\n')
    for line in lines:
        if line.strip():
            parts = line.split()
            if len(parts) >= 2:
                category = parts[0]
                symbol = parts[1]
                if category in updates:
                    updates[category].append(symbol)
                else:
                    updates[category] = [symbol]
    return updates


