                .buttonStyle(PlainButtonStyle())

                // 付费套餐卡片
                Button(action: {
                    handlePurchase()
                }) {
                    HStack {
                        VStack(alignment: .leading, spacing: 8) {
                            Text("专业版\n(订阅时长 1 Month)")
                                .font(.title2.bold())
                                .foregroundColor(.primary)
                            Text("不限次检索和查询所有数据")
