                    }
                    .disabled(audioPlayerManager.isSynthesizing)

                    Button { isSharePresented = true } label: { Image(systemName: "square.and.arrow.up") }
                }
                // 【修改点1】这里添加 .primary 颜色，使图标变为黑白（跟随系统主题）
                .foregroundColor(.primary)
            }
