struct SourceIconView: View {
    let sourceName: String

    // 自定义映射表：如果想让某些特定的源显示特定的缩写，可以在这里配置
    // 例如：["华尔街日报": "WSJ", "New York Times": "NYT"]
    private let customAbbreviations: [String: String] = [
        "环球资讯": "WSJ",
        "一手新闻源": "WSJ",
        "欧美媒体": "FT",
        "海外视角": "WP",
        "最酷最敢说": "B",
        "时政锐评": "日",
        "英文期刊": "NYT",
        "前沿技术": "经",
        "语音播报": "Reu",
        "可以听的新闻": "MIT",
        "麻省理工技术评论": "MIT"
    ]

    var body: some View {
        // 1. 优先尝试加载图片
        // UIImage(named:) 会在 Assets 中查找完全匹配名字的图片
        if let _ = UIImage(named: sourceName) {
            Image(sourceName)
                .resizable()
                .scaledToFit() // 保持比例填充
                .frame(width: 40, height: 40)
                // 给图片加一点圆角，类似 App 图标的样式（方圆形），比纯圆更现代
                .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
                .shadow(color: Color.black.opacity(0.1), radius: 2, x: 0, y: 1)
        } else {
            // 2. 如果没有图片，回退到文字 Logo
            ZStack {
                // 背景色：可以使用随机色，或者根据名字哈希生成固定颜色，这里暂时用统一的高级灰
                RoundedRectangle(cornerRadius: 10, style: .continuous)
                    .fill(Color.blue.opacity(0.1)) // 淡蓝色背景

                Text(getDisplayText())
                    .font(.system(size: 18, weight: .bold, design: .rounded))
                    .foregroundColor(.blue) // 蓝色文字
            }
            .frame(width: 40, height: 40)
        }
    }

    // 获取要显示的文字
    private func getDisplayText() -> String {
        // 如果在自定义字典里有，就用字典的
        if let abbr = customAbbreviations[sourceName] {
            return abbr
        }
        // 否则取前两个字符（如果只有1个字就取1个），看起来比1个字更丰富
        return String(sourceName.prefix(1))
    }
}

import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext
    // 【新增】标记是否在页面出现时自动开始播放
    let autoPlayOnAppear: Bool

    @ObservedObject var viewModel: NewsViewModel
    @ObservedObject var resourceManager: ResourceManager

    @StateObject private var audioPlayerManager = AudioPlayerManager()

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    @State private var unreadCountForGroup: Int = 0
    @State private var totalUnreadCountForContext: Int = 0

    @State private var showNoNextToast = false
    @State private var isMiniPlayerCollapsed = false

    @State private var didCommitOnDisappear = false

    // 【修改】更新图片下载状态变量以支持详细进度
    @State private var isDownloadingImages = false
    @State private var downloadProgress: Double = 0.0
    @State private var downloadProgressText = ""

    @State private var showErrorAlert = false
    @State private var errorMessage = ""

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel, resourceManager: ResourceManager, autoPlayOnAppear: Bool = false) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel
        self.resourceManager = resourceManager
        self.autoPlayOnAppear = autoPlayOnAppear // 【新增】赋值

        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCountForGroup: unreadCountForGroup,
                totalUnreadCount: totalUnreadCountForContext,
                viewModel: viewModel,
                audioPlayerManager: audioPlayerManager, // 保持传递以获取状态
                requestNextArticle: {
                    await self.switchToNextArticleAndStopAudio()
                },
                // 【修改】传递 onAudioToggle 闭包
                onAudioToggle: {
                    handleAudioToggle()
                }
            )
            .id(currentArticle.id)
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                ToastView(message: "该分组内已无更多文章")
            }

            // 常驻的悬浮按钮
            MiniAudioBubbleView(
                isPlaybackActive: audioPlayerManager.isPlaybackActive,
                onTap: { handleBubbleTap() }
            )
            .padding(.bottom, 10)
            .transition(.move(edge: .leading).combined(with: .opacity))
            .zIndex(2) // 确保在详情页之上

            // 条件显示的完整播放器
            if !isMiniPlayerCollapsed && audioPlayerManager.isPlaybackActive {
                AudioPlayerView(
                    playerManager: audioPlayerManager,
                    playNextAndStart: {
                        Task {
                            await switchToNextArticle(shouldAutoplayNext: true)
                        }
                    },
                    toggleCollapse: {
                        withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                            isMiniPlayerCollapsed = true
                        }
                    }
                )
                .padding(.horizontal)
                // 【修改】增大底部间距，将播放器整体上移，避免重叠
                .padding(.bottom, 30)
                .transition(.move(edge: .bottom).combined(with: .opacity))
                .zIndex(3) // 确保在悬浮按钮之上
            }

            // 更新图片下载遮罩层UI以显示详细进度
            if isDownloadingImages {
                VStack(spacing: 12) {
                    Text("正在加载图片...")
                        .font(.headline)
                        .foregroundColor(.white)

                    ProgressView(value: downloadProgress)
                        .progressViewStyle(LinearProgressViewStyle(tint: .white))
                        .padding(.horizontal, 40)

                    Text(downloadProgressText)
                        .font(.caption)
                        .foregroundColor(.white.opacity(0.8))
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(Color.black.opacity(0.75))
                .edgesIgnoringSafeArea(.all)
                .zIndex(4) // 最高层级
            }
        }
        .onAppear {
            didCommitOnDisappear = false
            updateUnreadCounts()

            Task {
                await preDownloadNextArticleImages()
            }

            audioPlayerManager.onNextRequested = {
                Task {
                    await self.switchToNextArticle(shouldAutoplayNext: true)
                }
            }
            audioPlayerManager.onPlaybackFinished = { }

            // 【新增】处理进入页面后的自动播放逻辑
            if autoPlayOnAppear {
                // 稍微延迟一点，确保视图加载完成，且避免和系统的转场动画冲突
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                    if !audioPlayerManager.isPlaybackActive {
                        startPlayback()
                    }
                }
            }
        }
        .onDisappear {
            guard !didCommitOnDisappear else { return }
            didCommitOnDisappear = true

            audioPlayerManager.stop()
            _ = viewModel.stageArticleAsRead(articleID: currentArticle.id)
            viewModel.commitPendingReads()
        }
        .onChange(of: currentArticle) { _, newArticle in
            updateUnreadCounts()
            Task {
                await preDownloadNextArticleImages()
            }
        }
        .background(Color.viewBackground.ignoresSafeArea())
        .alert("", isPresented: $showErrorAlert, actions: {
            Button("好的", role: .cancel) { }
        }, message: {
            Text(errorMessage)
        })
    }

    // 【修改】更新处理悬浮按钮点击的逻辑
    private func handleBubbleTap() {
        // 【新增逻辑】如果完整播放器是展开状态，并且音频正在播放，则点击悬浮按钮执行最小化操作
        if !isMiniPlayerCollapsed && audioPlayerManager.isPlaybackActive {
            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                isMiniPlayerCollapsed = true
            }
        }
        // 如果音频正在播放（但播放器是收起的），点击悬浮按钮则展开完整播放器
        else if audioPlayerManager.isPlaybackActive {
            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                isMiniPlayerCollapsed = false
            }
        } else {
            // 如果未播放，点击则开始播放
            startPlayback()
        }
    }

    // 处理右上角工具栏按钮点击的逻辑
    private func handleAudioToggle() {
        if audioPlayerManager.isPlaybackActive {
            audioPlayerManager.stop()
        } else {
            startPlayback()
        }
    }

    // 一个统一的开始播放的辅助函数
    private func startPlayback() {
        // 开始播放时，确保完整播放器是展开状态
        isMiniPlayerCollapsed = false

        let paragraphs = currentArticle.article
            .components(separatedBy: .newlines)
            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
        let fullText = paragraphs.joined(separator: "\n\n")
        audioPlayerManager.startPlayback(text: fullText, title: currentArticle.topic)
    }

    private func updateUnreadCounts() {
        let sourceNameToUse: String?
        switch navigationContext {
        case .fromSource(let name):
            sourceNameToUse = name
        case .fromAllArticles:
            sourceNameToUse = nil
        }

        self.unreadCountForGroup = viewModel.getUnreadCountForDateGroup(
            timestamp: currentArticle.timestamp,
            inSource: sourceNameToUse
        )
        self.totalUnreadCountForContext = viewModel.getEffectiveUnreadCount(
            inSource: sourceNameToUse
        )
    }

    private func switchToNextArticleAndStopAudio() async {
        audioPlayerManager.stop()
        await switchToNextArticle(shouldAutoplayNext: false)
    }

    private func switchToNextArticle(shouldAutoplayNext: Bool) async {
        if shouldAutoplayNext {
            audioPlayerManager.prepareForNextTransition()
        }

        _ = viewModel.stageArticleAsRead(articleID: currentArticle.id)

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        guard let next = viewModel.findNextUnread(after: currentArticle.id, inSource: sourceNameToSearch) else {
            await MainActor.run {
                showToast { shouldShow in self.showNoNextToast = shouldShow }
                audioPlayerManager.stop()
            }
            return
        }

        if !next.article.images.isEmpty {
            let imagesAlreadyExist = resourceManager.checkIfImagesExistForArticle(
                timestamp: next.article.timestamp,
                imageNames: next.article.images
            )

            if !imagesAlreadyExist {
                // 1. 设置下载状态的初始值
                await MainActor.run {
                    isDownloadingImages = true
                    downloadProgress = 0.0
                    downloadProgressText = "准备中..."
                }

                do {
                    // 2. 调用下载方法，并传入一个闭包来处理进度更新
                    try await resourceManager.downloadImagesForArticle(
                        timestamp: next.article.timestamp,
                        imageNames: next.article.images,
                        progressHandler: { current, total in
                            // 这个闭包会在 MainActor 上被调用，可以直接更新UI状态
                            self.downloadProgress = total > 0 ? Double(current) / Double(total) : 0
                            self.downloadProgressText = "已下载 \(current) / \(total)"
                        }
                    )
                } catch {
                    await MainActor.run {
                        isDownloadingImages = false
                        errorMessage = "图片下载失败: \(error.localizedDescription)"
                        showErrorAlert = true
                        audioPlayerManager.stop()
                    }
                    return // 下载失败，中断切换
                }

                // 3. 下载成功后，隐藏遮罩
                await MainActor.run {
                    isDownloadingImages = false
                }
            }
        }

        // 切换文章的动画
        await MainActor.run {
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
        }

        if shouldAutoplayNext {
            await MainActor.run {
                // 自动播放时，确保播放器是展开的
                self.isMiniPlayerCollapsed = false
                let paragraphs = next.article.article
                    .components(separatedBy: .newlines)
                    .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                let fullText = paragraphs.joined(separator: "\n\n")
                self.audioPlayerManager.startPlayback(text: fullText, title: next.article.topic)
            }
        }
    }

    private func preDownloadNextArticleImages() async {
        print("开始检查并预下载下一篇文章的图片...")

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        guard let next = viewModel.findNextUnread(after: currentArticle.id, inSource: sourceNameToSearch) else {
            print("没有找到下一篇未读文章，无需预下载。")
            return
        }

        guard !next.article.images.isEmpty else {
            print("下一篇文章 '\(next.article.topic)' 没有图片，无需预下载。")
            return
        }

        do {
            try await resourceManager.preDownloadImagesForArticleSilently(
                timestamp: next.article.timestamp,
                imageNames: next.article.images
            )
        } catch {
            print("静默预下载下一篇文章的图片失败: \(error.localizedDescription)")
        }
    }

    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }

    struct ToastView: View {
        let message: String

        var body: some View {
            Text(message)
                .font(.subheadline)
                .padding()
                .background(Color.black.opacity(0.75))
                .foregroundColor(.white)
                .cornerRadius(10)
                .padding(.bottom, 50)
                .transition(.opacity.animation(.easeInOut))
        }
    }
}

import SwiftUI

enum ArticleFilterMode: String, CaseIterable {
    case unread = "未读"
    case read = "已读"
}

// ==================== 公共协议和扩展 ====================
protocol ArticleListDataSource {
    var baseFilteredArticles: [ArticleItem] { get }
    var filterMode: ArticleFilterMode { get }
}

struct ArticleItem: Identifiable {
    let id: UUID
    let article: Article
    let sourceName: String?
    var isContentMatch: Bool = false // 【新增】增加内容匹配标志，并提供默认值

    // 【修改】更新初始化方法以支持 isContentMatch
    init(article: Article, sourceName: String? = nil, isContentMatch: Bool = false) {
        self.id = article.id
        self.article = article
        self.sourceName = sourceName
        self.isContentMatch = isContentMatch
    }
}

struct ArticleListContent: View {
    let items: [ArticleItem]
    let filterMode: ArticleFilterMode
    let expandedTimestamps: Set<String>
    let viewModel: NewsViewModel
    // 【新增】传入 AuthManager 以判断登录状态
    let authManager: AuthManager
    let onToggleTimestamp: (String) -> Void
    let onArticleTap: (ArticleItem) async -> Void

    var groupedArticles: [String: [ArticleItem]] {
        let initial = Dictionary(grouping: items, by: { $0.article.timestamp })
        if filterMode == .read {
            return initial.mapValues { Array($0.reversed()) }
        } else {
            return initial
        }
    }

    var sortedTimestamps: [String] {
        // 【修改】统一将日期分组排序改为降序（新->旧）。
        // 这样未读列表也会将最新的日期显示在最上方。
        return groupedArticles.keys.sorted(by: >)
    }

    var body: some View {
        ForEach(sortedTimestamps, id: \.self) { timestamp in
            Section {
                if expandedTimestamps.contains(timestamp) {
                    ForEach(groupedArticles[timestamp] ?? []) { item in
                        // 【修改】将 authManager 传递下去
                        ArticleRowButton(
                            item: item,
                            filterMode: filterMode,
                            viewModel: viewModel,
                            authManager: authManager,
                            filteredArticles: items,
                            onTap: { await onArticleTap(item) }
                        )
                    }
                }
            } header: {
                // 【修改】锁定条件：未订阅 且 时间戳被锁定
                let isLocked = !authManager.isSubscribed && viewModel.isTimestampLocked(timestamp: timestamp)
                TimestampHeader(
                    timestamp: timestamp,
                    count: groupedArticles[timestamp]?.count ?? 0,
                    isExpanded: expandedTimestamps.contains(timestamp),
                    isLocked: isLocked, // 传递锁定状态
                    onToggle: { onToggleTimestamp(timestamp) }
                )
            }
        }
    }
}

struct SearchResultsList: View {
    let results: [ArticleItem]
    let viewModel: NewsViewModel
    // 【新增】传入 AuthManager
    let authManager: AuthManager
    let onArticleTap: (ArticleItem) async -> Void

    // 【优化】静态 formatter
    private static let parsingFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateFormat = "yyMMdd"
        return f
    }()

    private static let displayFormatter: DateFormatter = {
        let f = DateFormatter()
        f.locale = Locale(identifier: "zh_CN")
        f.dateFormat = "yyyy年M月d日, EEEE"
        return f
    }()

    var groupedResults: [String: [ArticleItem]] {
        var initial = Dictionary(grouping: results, by: { $0.article.timestamp })
        initial = initial.mapValues { Array($0.reversed()) }
        return initial
    }

    var sortedTimestamps: [String] {
        groupedResults.keys.sorted(by: >)
    }

    var body: some View {
        if results.isEmpty {
            Section {
                Text("未找到匹配的文章")
                    .foregroundColor(.secondary)
                    .padding(.vertical, 12)
                    .listRowBackground(Color.clear)
            } header: {
                Text("搜索结果")
                    .font(.headline)
                    .foregroundColor(.blue.opacity(0.7))
                    .padding(.vertical, 4)
            }
        } else {
            ForEach(sortedTimestamps, id: \.self) { timestamp in
                Section(header:
                    VStack(alignment: .leading, spacing: 2) {
                        Text("搜索结果")
                            .font(.subheadline)
                            .foregroundColor(.blue.opacity(0.7))
                        HStack {
                            Text("\(formatTimestamp(timestamp)) (\(groupedResults[timestamp]?.count ?? 0))")
                                .font(.headline)
                                .foregroundColor(.blue.opacity(0.85))
                            // 【修改】锁定条件：未订阅 且 时间戳被锁定
                            if !authManager.isSubscribed && viewModel.isTimestampLocked(timestamp: timestamp) {
                                Image(systemName: "lock.fill")
                                    .foregroundColor(.yellow.opacity(0.8))
                                    .font(.footnote)
                            }
                        }
                    }
                    .padding(.vertical, 4)
                ) {
                    ForEach(groupedResults[timestamp] ?? []) { item in
                        // 【修改】传递 authManager
                        ArticleRowButton(
                            item: item,
                            filterMode: .unread, // 搜索结果统一按未读模式处理上下文菜单
                            viewModel: viewModel,
                            authManager: authManager,
                            filteredArticles: [],
                            onTap: { await onArticleTap(item) }
                        )
                    }
                }
            }
        }
    }

    private func formatTimestamp(_ timestamp: String) -> String {
        guard let date = Self.parsingFormatter.date(from: timestamp) else { return timestamp }
        return Self.displayFormatter.string(from: date)
    }
}

