// MARK: - ComparisonChartView (修改：添加时间范围切换逻辑)
struct ComparisonChartView: View {
    let symbols: [String]
    // 初始传入的日期，仅作为默认值
    let startDate: Date
    let endDate: Date

    @EnvironmentObject var dataService: DataService
    @State private var chartData: [String: [DatabaseManager.PriceData]] = [:]
    @State private var isLoading = false
    @State private var errorMessage: String? = nil

    // 【新增】用于内部管理的日期状态
    @State private var currentStartDate: Date = Date()
    @State private var currentEndDate: Date = Date()
    @State private var selectedTimeRange: TimeRange? = nil // nil 表示自定义（初始）范围

    // 可用的时间范围
    private let availableRanges: [TimeRange] = [.oneMonth, .threeMonths, .sixMonths, .oneYear]

    var body: some View {
        VStack {
            if isLoading {
                ProgressView("加载数据...")
                    .scaleEffect(1.5, anchor: .center)
                    .frame(height: 350)
            } else if let errorMessage {
                Text(errorMessage)
                    .foregroundColor(.red)
                    .padding()
            } else {
                // 调用新的原生 Swift Charts 视图
                NativeComparisonChartView(data: chartData, isDarkMode: true)
                    .frame(height: 350)
                    .padding(.horizontal, 4)
                    .padding(.vertical)
            }

            // 【新增】时间范围切换按钮
            HStack(spacing: 15) {
                ForEach(availableRanges, id: \.title) { range in
                    Button(action: {
                        applyTimeRange(range)
                    }) {
                        Text(range.title)
                            .font(.system(size: 14, weight: selectedTimeRange == range ? .bold : .regular))
                            .padding(.vertical, 6)
                            .padding(.horizontal, 16)
                            .background(selectedTimeRange == range ? Color.blue.opacity(0.2) : Color.gray.opacity(0.1))
                            .foregroundColor(selectedTimeRange == range ? .blue : .primary)
                            .cornerRadius(8)
                    }
                }
            }
            .padding(.top, 10)
            .padding(.bottom, 20)

            Spacer()
        }
        .onAppear {
            // 初始化内部日期状态
            if currentStartDate == Date.distantPast || currentStartDate == currentEndDate {
                currentStartDate = startDate
                currentEndDate = endDate
            }
            loadComparisonData()
        }
        // 【新增】在此页面彻底禁用侧滑返回手势
        // 这需要依赖你在 ChartView.swift 中定义的 NavigationPopGestureDisabler
        // 如果提示找不到，请把那个结构体也复制到这个文件底部，或者确保它是 public/internal 可见的
        .background(NavigationPopGestureDisabler(disabled: true))
    }

    // 【新增】应用时间范围
    private func applyTimeRange(_ range: TimeRange) {
        selectedTimeRange = range
        // TimeRange.startDate 是基于 Date() 计算的，通常我们希望结束日期是今天
        currentEndDate = Date()
        currentStartDate = range.startDate
        loadComparisonData()
    }

    private func loadComparisonData() {
        isLoading = true
        errorMessage = nil

        // 使用 Task
        Task {
            var tempData: [String: [DatabaseManager.PriceData]] = [:]
            var shortestDateRange: (start: Date, end: Date)?
            var errorMsg: String? = nil

            // 并发获取数据
            await withTaskGroup(of: (String, [DatabaseManager.PriceData]?).self) { group in
                for symbol in symbols {
                    group.addTask {
                        guard let tableName = await MainActor.run(body: { dataService.getCategory(for: symbol) }) else {
                            return (symbol, nil) // 找不到分类
                        }

                        // 使用当前的内部日期范围
                        let data = await DatabaseManager.shared.fetchHistoricalData(
                            symbol: symbol,
                            tableName: tableName,
                            dateRange: .customRange(start: currentStartDate, end: currentEndDate)
                        )
                        return (symbol, data)
                    }
                }

                for await (symbol, data) in group {
                    if let data = data, !data.isEmpty {
                        tempData[symbol] = data
                    } else {
                        // 只要有一个失败，就标记错误（或者你可以选择忽略失败的）
                        if errorMsg == nil { errorMsg = "未找到 \(symbol) 的数据" }
                    }
                }
            }

            if let error = errorMsg {
                await MainActor.run {
                    self.errorMessage = error
                    self.isLoading = false
                }
                return
            }

            // 数据处理逻辑
            for (symbol, data) in tempData {
                let sortedData = data.sorted { $0.date < $1.date }
                tempData[symbol] = sortedData

                let dataStart = sortedData.first?.date ?? currentStartDate
                let dataEnd = sortedData.last?.date ?? currentEndDate

                if let existingRange = shortestDateRange {
                    shortestDateRange = (
                        start: max(existingRange.start, dataStart),
                        end: min(existingRange.end, dataEnd)
                    )
                } else {
                    shortestDateRange = (dataStart, dataEnd)
                }
            }

            guard let dateRange = shortestDateRange else {
                await MainActor.run {
                    self.errorMessage = "无法确定共同的日期范围"
                    self.isLoading = false
                }
                return
            }

            for (symbol, data) in tempData {
                var filteredData = data.filter {
                    $0.date >= dateRange.start && $0.date <= dateRange.end
                }
                filteredData = filteredData.lttbSampled(threshold: 150)
                tempData[symbol] = filteredData
            }

            await MainActor.run {
