                                    HStack(spacing: 2) {
                                        Text("原文链接")
                                        Image(systemName: "arrow.up.right") // 加一个小图标增加辨识度
                                    }
                                    .font(.caption)
                                    .foregroundColor(.blue) // 经典的链接蓝色
                                }
                            }
                        }

