        console.log('WSJ Scraper loaded');

    });

    // 对于动态加载的内容，添加 MutationObserver 来监测DOM变化
    function throttle(func, limit) {
        let inThrottle;
        return function () {
            const args = arguments;
            const context = this;
            if (!inThrottle) {
                func.apply(context, args);
                inThrottle = true;
                setTimeout(() => inThrottle = false, limit);
            }
        }
    }

    // 在观察到DOM变化后，仅执行第二次抓取并下载
