                    }
                }
            )
        }
        // 2. 微信引导页
        .sheet(isPresented: $showWeChatGuideSheet) {
            WeChatGuideView()
        }
        // 3. 原生系统分享（作为“更多”选项）
        .sheet(isPresented: $showSystemActivitySheet) {
