                            ArticleListContent(
                                items: baseFilteredArticles,
                                filterMode: filterMode,
                                expandedTimestamps: viewModel.expandedTimestampsBySource[sourceName, default: Set<String>()],
                                viewModel: viewModel,
                                authManager: authManager, // 传递
