struct SymbolItemView: View {
    let symbol: IndicesSymbol
    let sectorName: String
    @EnvironmentObject private var dataService: DataService
    @EnvironmentObject var authManager: AuthManager
    @EnvironmentObject var usageManager: UsageManager

    @State private var isNavigationActive = false
    @State private var showSubscriptionSheet = false

    // 【新增】用于存储异步获取的期权指标
    @State private var optionsMetrics: (iv: String, sum: String)? = nil
    @State private var showOptionsMetrics = false

    // 【定义】不需要改变显示逻辑的“经济数据”板块列表
    private let economySectors: Set<String> = [
        "ETFs", "Bonds", "Crypto", "Indices", "Currencies",
        "Economics", "Economic_All", "Commodities"
    ]

    private var earningTrend: EarningTrend {
        dataService.earningTrends[symbol.symbol.uppercased()] ?? .insufficientData
    }

    private var fallbackGroupName: String {
        switch sectorName {
        case "Economic_All": return "Economics"
        default: return sectorName
        }
    }

    private var groupName: String {
        dataService.getCategory(for: symbol.symbol) ?? fallbackGroupName
    }

    // 用于原逻辑的解析结构
    private struct ParsedValue {
        let prefix: String?
        let percentage: String?
        let suffix: String?
    }

    var body: some View {
        Button(action: {
            if usageManager.canProceed(authManager: authManager, action: .viewChart) {
                isNavigationActive = true
            } else {
                showSubscriptionSheet = true
            }
        }) {
            VStack(alignment: .leading, spacing: 8) {
                HStack {
                    Text(symbol.symbol)
                        .font(.headline)
                        .foregroundColor(colorForEarningTrend(earningTrend))

                    Spacer()

                    // 【核心修改】根据板块名称决定显示哪种视图
                    rightSideInfoView
                }

                if let tags = symbol.tags, !tags.isEmpty {
                    Text(tags.joined(separator: ", "))
                        .font(.footnote)
                        .foregroundColor(.secondary)
                        .lineLimit(2)
                        .multilineTextAlignment(.leading)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            .padding()
            .background(
                RoundedRectangle(cornerRadius: 12)
                    .fill(Color(.systemGray6))
                    .shadow(color: Color.black.opacity(0.05), radius: 2, x: 2, y: 2)
            )
            .padding(.vertical, 4)
        }
        .navigationDestination(isPresented: $isNavigationActive) {
            ChartView(symbol: symbol.symbol, groupName: groupName)
        }
        .sheet(isPresented: $showSubscriptionSheet) { SubscriptionView() }
        .onAppear {
            if earningTrend == .insufficientData {
                dataService.fetchEarningTrends(for: [symbol.symbol])
            }
        }
        // 【优化】只有非经济板块才加载期权数据
        .task {
            if !economySectors.contains(sectorName) {
                await loadOptionsMetrics()
            }
        }
    }

    // MARK: - 视图选择器
    @ViewBuilder
    private var rightSideInfoView: some View {
        if economySectors.contains(sectorName) {
            // 1. 经济数据：保持原样 (Prefix + Percentage + Suffix)
            originalCompareView
        } else {
            // 2. 股票/策略：新样式 (Prefix Only + Option Data)
            stockOptionStyleView
        }
    }

    // MARK: - 样式 1: 原有的显示逻辑 (用于经济数据)
    @ViewBuilder
    private var originalCompareView: some View {
        let parsed = parseOriginalValue(symbol.value)
        if parsed.prefix == nil && parsed.percentage == "N/A" && parsed.suffix == nil {
            Text("N/A")
                .foregroundColor(.gray)
                .fontWeight(.semibold)
        } else {
            HStack(spacing: 1) {
                if let prefix = parsed.prefix {
                    Text(prefix).foregroundColor(.orange)
                }
                if let percentage = parsed.percentage {
                    Text(percentage).foregroundColor(colorForPercentage(percentage))
                }
                if let suffix = parsed.suffix, !suffix.isEmpty {
                    Text(suffix).foregroundColor(.gray)
                }
            }
            .font(.system(size: 16)) // 保持原有大小
            .fontWeight(.semibold)
        }
    }

    // MARK: - 样式 2: 新的显示逻辑 (用于股票)
    @ViewBuilder
    private var stockOptionStyleView: some View {
        HStack(spacing: 8) { // 数值间稍微隔开

            // 1. 只提取前缀 (03后, 02前, 未)
            // 无论有没有期权数据，只要有前缀就显示
            if let prefix = extractPrefixOnly(from: symbol.value) {
                Text(prefix)
                    .foregroundColor(.orange)
                    .fontWeight(.semibold)
            }

            // 2. 显示期权数据 (IV 和 Sum)
            // 只有当 showOptionsMetrics 为 true (意味着日期校验通过) 时才显示
            if showOptionsMetrics, let metrics = optionsMetrics {
                // IV
                Text(metrics.iv)
                    .foregroundColor(colorForValueString(metrics.iv))
                    .fontWeight(.semibold)

                // Sum (Price + Change)
                Text(metrics.sum)
                    .foregroundColor(colorForValueString(metrics.sum))
                    .fontWeight(.semibold)
            }
        }
        .font(.system(size: 14)) // 字体稍小一点以适应更多数据
    }

    // MARK: - 逻辑处理方法

    // 加载并校验期权数据 (与 AppServer 和 DBManager 配合)
    private func loadOptionsMetrics() async {
        // 避免重复加载
        if optionsMetrics != nil { return }

        // 调用 DBManager 获取数据
        guard let summary = await DatabaseManager.shared.fetchOptionsSummary(forSymbol: symbol.symbol) else {
            return
        }

        // 校验日期：必须是系统日期的前一天 (Yesterday)
        guard let dateStr = summary.date else { return }

        // 获取昨天的日期字符串
        // 注意：这里简单使用 Calendar 计算。
        // 如果你的服务器返回的是 UTC 时间，而客户端是北京时间，可能需要注意时区。
        // 这里假设 AppServer 返回的 date 是 "YYYY-MM-DD" 格式的日期字符串，不带时分秒。
        let calendar = Calendar.current
        guard let yesterday = calendar.date(byAdding: .day, value: -1, to: Date()) else { return }

        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"
        let yesterdayStr = formatter.string(from: yesterday)

        // 【核心判断】日期必须匹配
        if dateStr == yesterdayStr {
            guard let iv = summary.iv, let price = summary.price, let change = summary.change else { return }

            let sum = price + change
            // 格式化 Sum，保留两位小数
            let sumStr = String(format: "%.2f", sum)

            await MainActor.run {
                self.optionsMetrics = (iv, sumStr)
                self.showOptionsMetrics = true
            }
        } else {
            // 日期不匹配，不显示数据
        }
    }

    // 解析原有的格式 (Prefix + Percentage + Suffix)
    private func parseOriginalValue(_ value: String) -> ParsedValue {
        if value == "N/A" {
            return ParsedValue(prefix: nil, percentage: "N/A", suffix: nil)
        }
        // 正则：(前缀)?(百分比)(后缀)?
        let pattern = #"^(\d+[前后未])?(-?\d+\.?\d*%)(\S*)?$"#
        if let regex = try? NSRegularExpression(pattern: pattern) {
            let range = NSRange(value.startIndex..<value.endIndex, in: value)
            if let match = regex.firstMatch(in: value, options: [], range: range) {

                var prefix: String? = nil
                var percentage: String? = nil
                var suffix: String? = nil

                let prefixRange = match.range(at: 1)
                if prefixRange.location != NSNotFound {
                    prefix = (value as NSString).substring(with: prefixRange)
                }

                let percentageRange = match.range(at: 2)
                if percentageRange.location != NSNotFound {
                    percentage = (value as NSString).substring(with: percentageRange)
                }

                let suffixRange = match.range(at: 3)
                if suffixRange.location != NSNotFound {
                    suffix = (value as NSString).substring(with: suffixRange)
                }

                return ParsedValue(prefix: prefix, percentage: percentage, suffix: suffix)
            }
        }
        // 如果匹配失败，直接把整个 value 当作 percentage 显示（容错）
        return ParsedValue(prefix: nil, percentage: value, suffix: nil)
    }

    // 【新逻辑】只提取前缀
    private func extractPrefixOnly(from value: String) -> String? {
        if value == "N/A" { return nil }
        // 只要匹配开头是 "数字+前后未" 即可
        let pattern = #"^(\d+[前后未])"#

        if let regex = try? NSRegularExpression(pattern: pattern) {
            let range = NSRange(value.startIndex..<value.endIndex, in: value)
            if let match = regex.firstMatch(in: value, options: [], range: range) {
                if let r = Range(match.range(at: 1), in: value) {
                    return String(value[r])
                }
            }
        }
        return nil
    }

    // 颜色判断辅助
    private func colorForPercentage(_ percentageString: String?) -> Color {
        guard let percentageString = percentageString else { return .white }
        let numericString = percentageString.replacingOccurrences(of: "%", with: "")
        guard let number = Double(numericString) else { return .white }
        if number > 0 { return .red }
        else if number < 0 { return .green }
        else { return .gray }
    }

    private func colorForValueString(_ valueStr: String) -> Color {
        // 去除 %, 空格 等非数字字符进行判断
        let cleanStr = valueStr.replacingOccurrences(of: "%", with: "").trimmingCharacters(in: .whitespaces)
        if let val = Double(cleanStr) {
            if val > 0 { return .red }
            if val < 0 { return .green }
        }
        return .gray
    }

    // ... (保留 colorForEarningTrend 等其他辅助函数)

    private func colorForEarningTrend(_ trend: EarningTrend) -> Color {
        switch trend {
        case .positiveAndUp: return .red
        case .negativeAndUp: return .purple
        case .positiveAndDown: return .cyan
        case .negativeAndDown: return .green
        case .insufficientData: return .primary
        }
    }
}

import Foundation

// 移除 SQLite3 引用，改为纯网络请求
class DatabaseManager {
    static let shared = DatabaseManager()

    // 服务器地址，请确保与 UpdateManager 中一致
    internal let serverBaseURL = "http://106.15.183.158:5001/api/Finance"

    private init() {}

    // 移除 reconnectToLatestDatabase，因为不再持有本地连接
    func reconnectToLatestDatabase() {
        // 空实现，保持兼容性
    }

    // MARK: - Models
    struct OptionsSummary: Codable {
        let call: String?
        let put: String?
        // 【新增】匹配服务器返回的 Price 和 Change
        let price: Double?
        let change: Double?
        // 【新增】IV 字段
        let iv: String?
        // 【本次新增】日期字段，用于前端校验
        let date: String?

        // 【新增】次新 IV
        let prev_iv: String? 
        // 【本次新增】次新数据的 Price 和 Change
        let prev_price: Double?
        let prev_change: Double?
    }

    struct MarketCapInfo: Codable {
        let symbol: String
        let marketCap: Double
        let peRatio: Double?
        let pb: Double?
    }

    struct PriceData: Identifiable, Codable {
        let id: Int
        let date: Date
        let price: Double
        let volume: Int64?

        // 自定义解码以处理日期字符串
        enum CodingKeys: String, CodingKey {
            case id, date, price, volume
        }

        init(id: Int, date: Date, price: Double, volume: Int64?) {
            self.id = id
            self.date = date
            self.price = price
            self.volume = volume
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            id = try container.decode(Int.self, forKey: .id)
            price = try container.decode(Double.self, forKey: .price)
            volume = try container.decodeIfPresent(Int64.self, forKey: .volume)

            let dateString = try container.decode(String.self, forKey: .date)
            let formatter = DateFormatter()
            formatter.dateFormat = "yyyy-MM-dd"
            if let date = formatter.date(from: dateString) {
                self.date = date
            } else {
                self.date = Date.distantPast // Fallback
            }
        }
    }

    // MARK: - Models (追加新的模型)
    struct OptionHistoryItem: Codable, Identifiable {
        let id = UUID() //以此符合 Identifiable
        let date: Date
        let price: Double

        enum CodingKeys: String, CodingKey {
            case date, price
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            price = try container.decode(Double.self, forKey: .price)

            let dateString = try container.decode(String.self, forKey: .date)
            let formatter = DateFormatter()
            formatter.dateFormat = "yyyy-MM-dd"
            // 容错处理
            if let date = formatter.date(from: dateString) {
                self.date = date
            } else {
                self.date = Date.distantPast
            }
        }
    }

    struct EarningData: Codable {
        let date: Date
        let price: Double

        enum CodingKeys: String, CodingKey {
            case date, price
        }

        init(date: Date, price: Double) {
            self.date = date
            self.price = price
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            price = try container.decode(Double.self, forKey: .price)
            let dateString = try container.decode(String.self, forKey: .date)
            let formatter = DateFormatter()
            formatter.dateFormat = "yyyy-MM-dd"
            if let date = formatter.date(from: dateString) {
                self.date = date
            } else {
                self.date = Date.distantPast
            }
        }
    }

    enum DateRangeInput {
        case timeRange(TimeRange)
        case customRange(start: Date, end: Date)
    }

    // MARK: - API Requests

    // 1. 获取所有市值数据 (Async)
    func fetchAllMarketCapData(from tableName: String) async -> [MarketCapInfo] {
        // tableName 参数在服务器端目前硬编码为 MNSPP，但保留参数以兼容
        guard let url = URL(string: "\(serverBaseURL)/query/market_cap") else { return [] }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let results = try JSONDecoder().decode([MarketCapInfo].self, from: data)
            return results
        } catch {
            print("Network error fetching market cap: \(error)")
            return []
        }
    }

    // 2. 获取最新成交量 (Async)
    func fetchLatestVolume(forSymbol symbol: String, tableName: String) async -> Int64? {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/latest_volume") else { return nil }
        components.queryItems = [
            URLQueryItem(name: "symbol", value: symbol),
            URLQueryItem(name: "table", value: tableName)
        ]

        guard let url = components.url else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let response = try JSONDecoder().decode([String: Int64?].self, from: data)
            return response["volume"] ?? nil
        } catch {
            print("Network error fetching volume: \(error)")
            return nil
        }
    }

    // 3. 获取历史数据 (Async)
    func fetchHistoricalData(
        symbol: String,
        tableName: String,
        dateRange: DateRangeInput
    ) async -> [PriceData] {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/historical") else { return [] }

        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"

        let (startDate, endDate): (Date, Date) = {
            switch dateRange {
            case .timeRange(let timeRange):
                return (timeRange.startDate, Date())
            case .customRange(let start, let end):
                return (start, end)
            }
        }()

        components.queryItems = [
            URLQueryItem(name: "symbol", value: symbol),
            URLQueryItem(name: "table", value: tableName),
            URLQueryItem(name: "start", value: formatter.string(from: startDate)),
            URLQueryItem(name: "end", value: formatter.string(from: endDate))
        ]

        guard let url = components.url else { return [] }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let results = try JSONDecoder().decode([PriceData].self, from: data)
            return results
        } catch {
            print("Network error fetching historical data: \(error)")
            return []
        }
    }

    // 4. 获取财报数据 (Async)
    func fetchEarningData(forSymbol symbol: String) async -> [EarningData] {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/earning") else { return [] }
        components.queryItems = [URLQueryItem(name: "symbol", value: symbol)]

        guard let url = components.url else { return [] }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let results = try JSONDecoder().decode([EarningData].self, from: data)
            return results
        } catch {
            print("Network error fetching earning data: \(error)")
            return []
        }
    }

    // 5. 获取收盘价 (Async)
    func fetchClosingPrice(forSymbol symbol: String, onDate date: Date, tableName: String) async -> Double? {
        guard var components = URLComponents(string: "\(serverBaseURL)/query/closing_price") else { return nil }

        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"

        components.queryItems = [
            URLQueryItem(name: "symbol", value: symbol),
            URLQueryItem(name: "date", value: formatter.string(from: date)),
            URLQueryItem(name: "table", value: tableName)
        ]

        guard let url = components.url else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let response = try JSONDecoder().decode([String: Double?].self, from: data)
            return response["price"] ?? nil
        } catch {
            print("Network error fetching closing price: \(error)")
            return nil
        }
    }

