        self.ecoDataTimestamp = UserDefaults.standard.string(forKey: ecoDataKey)
        self.introSymbolTimestamp = UserDefaults.standard.string(forKey: introSymbolKey)
    }

    // 【新增】内部状态，标记是否正在加载
    private var isLoading = false 

    // MARK: - Published properties
