    var enrichedSectors: [IndicesSector] {
        let compareMap = dataService.compareData
        var tagMap: [String: [String]] = [:]
        if let stocks = dataService.descriptionData?.stocks {
            for stock in stocks {
                tagMap[stock.symbol.uppercased()] = stock.tag
