            // isEnglishMode = false 
            prepareContent()
        }
        .onChange(of: article) { _, _ in
            prepareContent()
        }
        // 【新增 4】监听语言模式切换，重新计算段落布局
        .onChange(of: isEnglishMode) { _, _ in
            prepareContent()
        }
        .toolbar {
            ToolbarItem(placement: .principal) {
                VStack(spacing: 2) {
                    Text(sourceName.replacingOccurrences(of: "_", with: " "))
