        let imagesAlreadyExist = resourceManager.checkIfImagesExistForArticle(
            timestamp: article.timestamp,
            imageNames: article.images
        )

        if imagesAlreadyExist {
            await MainActor.run {
                selectedArticleItem = (article, sourceName)
