                                    // 颜色适配：实心时文字反色，空心时文字主色
                                    .foregroundColor(isEnglishMode ? Color.viewBackground : Color.primary)
                            }
                            .frame(width: 24, height: 24)
                        }
                        // 稍微给个过渡动画
                        .transition(.scale.combined(with: .opacity))
                    }
                    Button(action: onAudioToggle) {
