        return viewModel.allArticlesSortedForDisplay.compactMap { item -> (Article, String, Bool)? in
            // 优先匹配标题
            if item.article.topic.lowercased().contains(keyword) {
                return (item.article, item.sourceName, false) // false 表示不是内容匹配
