        } message: {
            Text(errorMessage)
        }
        // 【修改】兑换码 Alert 双语化
        .alert(Localized.internalTestTitle, isPresented: $showRedeemAlert) {
            TextField(Localized.enterInviteCode, text: $inviteCode)
                .textInputAutocapitalization(.characters)
            Button(Localized.cancel, role: .cancel) { }
            Button(Localized.redeem) {
                handleRedeem()
            }
        } message: {
            Text(Localized.inviteCodeInstruction)
        }
        // 【修改】恢复结果 Alert 双语化
        .alert(Localized.restoreResult, isPresented: $showRestoreAlert) {
            Button(Localized.confirm, role: .cancel) {
                if authManager.isSubscribed {
                    dismiss()
                }
            }
        } message: {
            Text(restoreMessage)
        }
        // 【新增 2】绑定登录弹窗
        .sheet(isPresented: $showLoginSheet) {
            LoginView()
        }
        // ================== 【新增修复代码开始】 ==================
        // 监听登录状态，登录成功后自动关闭当前视图弹出的 LoginView
        .onChange(of: authManager.isLoggedIn) { _, newValue in
            if newValue == true && showLoginSheet {
                showLoginSheet = false
                // 可选：如果需要在登录后自动继续购买流程，可以在这里再次调用 handlePurchase()
                // handlePurchase() 
            }
        }
    }

    // 【修改】处理购买：先检查登录
    private func handlePurchase() {
        // 1. 检查是否已登录
        guard authManager.isLoggedIn else {
            showLoginSheet = true
            return
        }

        // 2. 开始购买流程
        isPurchasing = true

        Task {
            do {
                // 【核心修改】获取购买结果 (true/false)
                let isSuccess = try await authManager.purchaseSubscription()

                await MainActor.run {
                    isPurchasing = false

                    if isSuccess {
                        // 只有明确成功时，才关闭页面
                        print("支付成功，关闭订阅页面")
                        dismiss()
                    } else {
                        // 如果是取消(.userCancelled)或挂起，保持页面打开
                        print("用户取消或未完成支付，保留订阅页面")
                        // 这里不需要做任何操作，SubscriptionView 会继续显示
                    }
                }
            } catch {
                await MainActor.run {
                    isPurchasing = false
                    errorMessage = error.localizedDescription
                    showError = true
                }
            }
        }
    }

    // 【修改】处理恢复购买：先检查登录
    private func performRestore() {
        // 1. 检查是否已登录
        guard authManager.isLoggedIn else {
            showLoginSheet = true
            return
        }

        // 2. 已登录 -> 执行原有恢复逻辑
        isRestoring = true
        Task {
            do {
                try await authManager.restorePurchases()
                await MainActor.run {
                    isRestoring = false
                    // 【修改】恢复结果文案双语化
                    if authManager.isSubscribed {
                        restoreMessage = Localized.restoreSuccess
                    } else {
                        restoreMessage = Localized.restoreNotFound
                    }
                    showRestoreAlert = true
                }
            } catch {
                await MainActor.run {
                    isRestoring = false
                    // 使用专门的“恢复失败”词条
                    restoreMessage = "\(Localized.restoreFailed): \(error.localizedDescription)"
                    showRestoreAlert = true
                }
            }
        }
    }

    // 【修改】处理兑换逻辑：建议也加上登录检查
    private func handleRedeem() {
        guard !inviteCode.isEmpty else { return }

        // 建议加上：确保有 UserID 绑定
        guard authManager.isLoggedIn else {
            showLoginSheet = true
            return
        }

        isRedeeming = true
        Task {
            // ... (原有兑换逻辑保持不变)
            do {
                try await authManager.redeemInviteCode(inviteCode)
                await MainActor.run {
                    isRedeeming = false
                    inviteCode = ""
                    dismiss()
                }
            } catch {
                await MainActor.run {
                    isRedeeming = false
                    inviteCode = ""
                    errorMessage = error.localizedDescription
                    showError = true
                }
            }
        }
    }
}

