    func checkAndDownloadAllNewsManifests(isManual: Bool = false) async throws {
        self.isSyncing = true
        self.isDownloading = false
        self.syncMessage = Localized.fetchingManifest // 【修改】
        self.progressText = ""
        self.downloadProgress = 0.0

        do {
            let serverVersion = try await getServerVersion()

            // 【新增】获取到配置后，立即更新
            self.serverLockedDays = serverVersion.locked_days ?? 0

            let allJsonInfos = serverVersion.files
                .filter { $0.type == "json" && $0.name.starts(with: "onews_") }
                .sorted { $0.name < $1.name }

            if allJsonInfos.isEmpty {
                self.isSyncing = false
                return
            }

            var tasksToDownload: [FileInfo] = []
            for jsonInfo in allJsonInfos {
                let localURL = documentsDirectory.appendingPathComponent(jsonInfo.name)
                var shouldDownload = false

                if fileManager.fileExists(atPath: localURL.path) {
                    if let serverMD5 = jsonInfo.md5, let localMD5 = calculateMD5(for: localURL) {
                        if serverMD5 != localMD5 {
                            print("MD5不匹配，需要更新: \(jsonInfo.name)")
                            shouldDownload = true
                        } else {
                            print("已是最新: \(jsonInfo.name)")
                        }
                    } else {
                        print("缺少MD5，强制重新下载: \(jsonInfo.name)")
                        shouldDownload = true
                    }
                } else {
                    print("本地不存在，准备下载: \(jsonInfo.name)")
                    shouldDownload = true
                }

                if shouldDownload {
                    tasksToDownload.append(jsonInfo)
                }
            }

            if tasksToDownload.isEmpty {
                if isManual {
                    self.isSyncing = false
                    self.showAlreadyUpToDateAlert = true
                } else {
                    self.isSyncing = false
                }
                return
            }

            self.isDownloading = true
            let total = tasksToDownload.count
            for (index, info) in tasksToDownload.enumerated() {
                self.progressText = "\(index + 1)/\(total)"
                self.downloadProgress = Double(index + 1) / Double(total)
                self.syncMessage = Localized.downloadingData // 【修改】
                try await downloadSingleFile(named: info.name)
            }

            self.isDownloading = false
            // self.syncMessage = "新闻源已准备就绪！\n\n请点击右下角“+”按钮。"
            self.progressText = ""
            resetStateAfterDelay()

        } catch {
            self.isSyncing = false
            self.isDownloading = false
            throw error
        }
    }

    func checkAndDownloadUpdates(isManual: Bool = false) async throws {
        self.isSyncing = true
        self.isDownloading = false
        self.syncMessage = Localized.checkingUpdates // 【修改】
        self.progressText = ""
        self.downloadProgress = 0.0

        do {
            let serverVersion = try await getServerVersion()
            let localFiles = try getLocalFiles()

            // 【新增】获取到配置后，立即更新
            self.serverLockedDays = serverVersion.locked_days ?? 0
            print("ResourceManager: 从服务器获取到 locked_days = \(self.serverLockedDays)")

            self.syncMessage = Localized.cleaningOldResources // 【修改】
            let validServerFiles = Set(serverVersion.files.map { $0.name })
            let filesToDelete = localFiles.subtracting(validServerFiles)
            let oldNewsItemsToDelete = filesToDelete.filter {
                $0.starts(with: "onews_") || $0.starts(with: "news_images_")
            }

            if !oldNewsItemsToDelete.isEmpty {
                print("发现需要清理的过时资源: \(oldNewsItemsToDelete)")
                for itemName in oldNewsItemsToDelete {
                    let itemURL = documentsDirectory.appendingPathComponent(itemName)
                    try? fileManager.removeItem(at: itemURL)
                    print("🗑️ 已成功删除: \(itemName)")
                }
            } else {
                print("本地资源无需清理。")
            }

            var downloadTasks: [(fileInfo: FileInfo, isIncremental: Bool)] = []

            let jsonFilesFromServer = serverVersion.files.filter { $0.type == "json" }
            let imageDirsFromServer = serverVersion.files.filter { $0.type == "images" }

            for jsonInfo in jsonFilesFromServer {
                let localFileURL = documentsDirectory.appendingPathComponent(jsonInfo.name)
                let correspondingImageDirName = "news_images_" + jsonInfo.name.components(separatedBy: "_").last!.replacingOccurrences(of: ".json", with: "")

                if fileManager.fileExists(atPath: localFileURL.path) {
                    guard let serverMD5 = jsonInfo.md5, let localMD5 = calculateMD5(for: localFileURL) else {
                        print("警告: 无法获取 \(jsonInfo.name) 的 MD5，跳过检查。")
                        continue
                    }

                    if serverMD5 != localMD5 {
                        print("MD5不匹配: \(jsonInfo.name)。计划更新。")
                        downloadTasks.append((fileInfo: jsonInfo, isIncremental: false))
                        let imageDirURL = documentsDirectory.appendingPathComponent(correspondingImageDirName)
                        try? fileManager.createDirectory(at: imageDirURL, withIntermediateDirectories: true)
                    } else {
                        print("MD5匹配: \(jsonInfo.name) 已是最新。")
                    }

                } else {
                    print("新文件: \(jsonInfo.name)。计划下载。")
                    downloadTasks.append((fileInfo: jsonInfo, isIncremental: false))
                    let imageDirURL = documentsDirectory.appendingPathComponent(correspondingImageDirName)
                    try? fileManager.createDirectory(at: imageDirURL, withIntermediateDirectories: true)
                }
            }

            for dirInfo in imageDirsFromServer {
                let localDirURL = documentsDirectory.appendingPathComponent(dirInfo.name)
                try? fileManager.createDirectory(at: localDirURL, withIntermediateDirectories: true)
            }

            if downloadTasks.isEmpty {
                if isManual {
                    self.syncMessage = Localized.upToDate // 【修改】
                    resetStateAfterDelay()
                } else {
                    self.isSyncing = false
                }
                return
            }

            print("需要处理的任务列表: \(downloadTasks.map { $0.fileInfo.name })")

            self.isDownloading = true
            let totalTasks = downloadTasks.count

            for (index, task) in downloadTasks.enumerated() {
                self.progressText = "\(index + 1)/\(totalTasks)"
                self.downloadProgress = Double(index + 1) / Double(totalTasks)

                if task.fileInfo.type == "json" {
                    self.syncMessage = Localized.downloadingFiles // 【修改】
                    try await downloadSingleFile(named: task.fileInfo.name)
                }
            }

            self.isDownloading = false
            self.syncMessage = Localized.updateComplete // 【修改】
            self.progressText = ""
            resetStateAfterDelay()

        } catch {
            self.isSyncing = false
            self.isDownloading = false
            throw error
        }
    }

    private func resetStateAfterDelay(seconds: TimeInterval = 2) {
        Task {
            try? await Task.sleep(for: .seconds(seconds))
            await MainActor.run {
                self.isSyncing = false
                self.syncMessage = ""
                self.progressText = ""
            }
        }
    }

    private func calculateMD5(for fileURL: URL) -> String? {
        var hasher = Insecure.MD5()
        do {
            let handle = try FileHandle(forReadingFrom: fileURL)
            defer { handle.closeFile() }
            while true {
                let data = handle.readData(ofLength: 1024 * 1024)
                if data.isEmpty { break }
                hasher.update(data: data)
            }
            let digest = hasher.finalize()
            return digest.map { String(format: "%02hhx", $0) }.joined()
        } catch {
            print("错误：计算文件 \(fileURL.lastPathComponent) 的 MD5 失败: \(error)")
            return nil
        }
    }

    private func getServerVersion() async throws -> ServerVersion {
        guard let url = URL(string: "\(serverBaseURL)/check_version") else { 
            throw URLError(.badURL) 
        }
        let (data, _) = try await urlSession.data(from: url)
        let version = try JSONDecoder().decode(ServerVersion.self, from: data)

        // 【新增】保存映射关系
        if let mappings = version.source_mappings {
            await MainActor.run {
                self.sourceMappings = mappings
            }
        }

        return version
    }

    private func getLocalFiles() throws -> Set<String> {
        let contents = try fileManager.contentsOfDirectory(atPath: documentsDirectory.path)
        return Set(contents)
    }

    private func downloadSingleFile(named filename: String) async throws {
        guard var components = URLComponents(string: "\(serverBaseURL)/download") else { throw URLError(.badURL) }
        components.queryItems = [URLQueryItem(name: "filename", value: filename)]
        guard let url = components.url else { throw URLError(.badURL) }

        let (tempURL, response) = try await urlSession.download(from: url)

        guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
            throw URLError(.badServerResponse)
        }

        let destinationURL = documentsDirectory.appendingPathComponent(filename)
        if fileManager.fileExists(atPath: destinationURL.path) {
            try fileManager.removeItem(at: destinationURL)
        }
        try fileManager.moveItem(at: tempURL, to: destinationURL)
    }
}

import SwiftUI
import Foundation

// 文件名: Source_Add.swift
// 职责: 提供一个列表，让用户能够添加或移除新闻源订阅。
// 职责: 集中管理用户的新闻源订阅列表，使用 UserDefaults 进行持久化存储。

class SubscriptionManager: ObservableObject {
    static let shared = SubscriptionManager() // 使用单例模式，方便全局访问

    // 【修改】Key 改名，明确存储的是 ID
    private let subscribedSourceIDsKey = "subscribedNewsSourceIDs"
    // 【兼容】保留旧 Key 用于迁移检查
    let oldSubscribedSourcesKey = "subscribedNewsSources"

    @Published var subscribedSourceIDs: Set<String> { // 【改为ID集合】
        didSet {
            saveSubscribedIDs()
            // print("订阅列表(ID)已更新并保存: \(subscribedSourceIDs)")
        }
    }

    private init() {
        let savedIDs = UserDefaults.standard.stringArray(forKey: subscribedSourceIDsKey) ?? []
        self.subscribedSourceIDs = Set(savedIDs)
    }

    private func saveSubscribedIDs() {
        UserDefaults.standard.set(Array(subscribedSourceIDs), forKey: subscribedSourceIDsKey)
    }

    // MARK: - 公共方法

    /// 根据 source_id 判断是否订阅
    func isSubscribed(sourceId: String) -> Bool {
        return subscribedSourceIDs.contains(sourceId)
    }

    func addSubscription(sourceId: String) {
        subscribedSourceIDs.insert(sourceId)
    }

    func removeSubscription(sourceId: String) {
        subscribedSourceIDs.remove(sourceId)
    }

    func subscribeToAll(_ sourceIds: [String]) {
        subscribedSourceIDs.formUnion(sourceIds)
    }

    /// 供外部调用的迁移方法：将旧的名称订阅转换为 ID 订阅
    func migrateOldSubscription(name: String, id: String) {
        // 读取旧的名称列表
        let oldNames = UserDefaults.standard.stringArray(forKey: oldSubscribedSourcesKey) ?? []
        if oldNames.contains(name) {
            print("迁移订阅: 发现旧名称订阅 [\(name)]，自动映射为 ID [\(id)]")
            addSubscription(sourceId: id)
        }
    }
}

struct AddSourceView: View {
    // 状态：存储 (ID, Name) 元组
    @State private var allAvailableSources: [(id: String, name: String)] = []
    @State private var isLoading = true
    @State private var errorMessage: String?

    // 订阅管理器
    @ObservedObject private var subscriptionManager = SubscriptionManager.shared

    // 获取资源管理器和语言设置
    @EnvironmentObject var resourceManager: ResourceManager 
    @AppStorage("isGlobalEnglishMode") private var isGlobalEnglishMode = false 

    // 用于判断显示逻辑（首次设置 vs. 后续添加）
    let isFirstTimeSetup: Bool
    var onComplete: (() -> Void)? // 仅在首次设置时使用
    var onConfirm: (() -> Void)?  // 非首次场景点击“确定”的回调（默认关闭页面）

    @Environment(\.presentationMode) var presentationMode

    // MARK: - 新增计算属性
    /// 计算是否所有可用源都已被订阅，用于禁用“一键添加”按钮
    private var areAllSourcesSubscribed: Bool {
        let allIDs = Set(allAvailableSources.map { $0.id })
        return subscriptionManager.subscribedSourceIDs.isSuperset(of: allIDs)
    }

    var body: some View {
        // 【修改 1】不再使用 ZStack 包裹，直接使用主容器
        Group {
            if isLoading {
                VStack(spacing: 16) {
                    ProgressView()
                        .scaleEffect(1.2)
                    Text(Localized.fetchingSources) // 【双语化】
                        .font(.subheadline)
                        .foregroundColor(.secondary)
                }
                .frame(maxHeight: .infinity)
                .background(Color.viewBackground) // 确保加载时也有背景色
            } else if let error = errorMessage {
                VStack(spacing: 16) {
                    Image(systemName: "exclamationmark.triangle.fill")
                        .font(.largeTitle)
                        .foregroundColor(.orange)
                    Text(error)
                        .multilineTextAlignment(.center)
                        .padding(.horizontal)
                        .foregroundColor(.secondary)

                    // 增加一个刷新按钮，方便出错后重试
                    Button(Localized.refresh) { // 【双语化】
                        loadAvailableSources()
                    }
                    .buttonStyle(.bordered)
                }
                .frame(maxHeight: .infinity)
                .background(Color.viewBackground)
            } else {
                // 【修改 2】主列表
                List {
                    Section {
                        ForEach(allAvailableSources, id: \.id) { source in
                            HStack {
                                Text(source.name)
                                    .fontWeight(.medium)
                                    // 【修改】文字颜色自适应
                                    .foregroundColor(.primary)
                                Spacer()

                                Button(action: {
                                    // 震动反馈
                                    let generator = UIImpactFeedbackGenerator(style: .light)
                                    generator.impactOccurred()

                                    withAnimation(.spring()) {
                                        if subscriptionManager.isSubscribed(sourceId: source.id) {
                                            subscriptionManager.removeSubscription(sourceId: source.id)
                                        } else {
                                            subscriptionManager.addSubscription(sourceId: source.id)
                                        }
                                    }
                                }) {
                                    Image(systemName: subscriptionManager.isSubscribed(sourceId: source.id) ? "checkmark.circle.fill" : "plus.circle")
                                        .font(.system(size: 24)) // 稍微调大一点更容易点
                                        .foregroundColor(subscriptionManager.isSubscribed(sourceId: source.id) ? .green : .blue)
                                }
                                .buttonStyle(PlainButtonStyle()) // 确保点击只触发按钮，不触发整行
                            }
                            .padding(.vertical, 6)
                        }
                    } header: {
                        Text(Localized.availableSources) // 【双语化】
                    }
                    // 【关键点】这里不需要 footer spacer 了，因为 safeAreaInset 会自动处理
                }
                .listStyle(.insetGrouped)
                // 【修改 3】使用 safeAreaInset 放置底部悬浮栏
                // 这会让 List 自动感知底部的空间，从而允许最后一行滚动到按钮上方
                .safeAreaInset(edge: .bottom) {
                    VStack(spacing: 0) {
                        Divider() // 顶部分割线

                        VStack(spacing: 12) {
                            // 一键全选按钮（高亮版）
                            if !areAllSourcesSubscribed {
                                Button(action: {
                                    let allIDs = allAvailableSources.map { $0.id }
                                    let generator = UIImpactFeedbackGenerator(style: .medium)
                                    generator.impactOccurred()
                                    withAnimation(.spring()) {
                                        subscriptionManager.subscribeToAll(allIDs)
                                    }
                                }) {
                                    HStack(spacing: 8) {
                                        Image(systemName: "checkmark.rectangle.stack.fill")
                                            .font(.system(size: 18))
                                        // 【双语化】一键添加所有 (n)
                                        Text("\(Localized.addAll) (\(allAvailableSources.count))")
                                            .fontWeight(.bold)
                                    }
                                    .font(.headline)
                                    .foregroundColor(.white)
                                    .frame(maxWidth: .infinity)
                                    .frame(height: 54)
                                    .background(
                                        LinearGradient(
                                            gradient: Gradient(colors: [Color.green, Color.mint]),
                                            startPoint: .leading,
                                            endPoint: .trailing
                                        )
                                    )
                                    .cornerRadius(16)
                                    .shadow(color: Color.green.opacity(0.4), radius: 8, x: 0, y: 4)
                                }
                                .transition(.scale.combined(with: .opacity))
                            }

                            // 完成设置按钮
                            Button(action: handleConfirm) {
                                // 【双语化】请至少选择一个 / 完成设置
                                Text(subscriptionManager.subscribedSourceIDs.isEmpty ? Localized.selectAtLeastOne : Localized.finishSetup)
                                    .font(.headline)
                                    .foregroundColor(subscriptionManager.subscribedSourceIDs.isEmpty ? .secondary : .white)
                                    .frame(maxWidth: .infinity)
                                    .frame(height: 50)
                                    .background(
                                        subscriptionManager.subscribedSourceIDs.isEmpty
                                        ? Color.secondary.opacity(0.2)
                                        : Color.blue
                                    )
                                    .cornerRadius(16)
                            }
                            .disabled(subscriptionManager.subscribedSourceIDs.isEmpty)
                        }
                        .padding(16)
                        // 适配 iPhone 底部 Home Indicator 区域
                        .padding(.bottom, 0)
                        .background(
                            Material.regular // 毛玻璃背景，让列表滚动到底下时有模糊效果
                        )
                    }
                }
            }
        }
        .navigationTitle(Localized.addSourceTitle) // 【双语化】
        .navigationBarTitleDisplayMode(.inline)
        // 移除右上角“完成”按钮，保留默认返回按钮
        .onAppear(perform: loadAvailableSources)
    }

    private func handleConfirm() {
        if isFirstTimeSetup {
            onComplete?()
        } else {
            if let onConfirm {
                onConfirm()
            } else {
                presentationMode.wrappedValue.dismiss()
            }
        }
    }

    /// 从 Documents 中所有 onews_*.json 文件合并所有分组名（去重、排序）
    private func loadAvailableSources() {
        isLoading = true
        errorMessage = nil

        // 【修复】在进入后台线程前，先从 ResourceManager 获取映射表
        // 这样 mappings 变量就在闭包的作用域内了
        let mappings = resourceManager.sourceMappings
        let currentLangIsEnglish = self.isGlobalEnglishMode // 捕获当前语言状态用于闭包

        DispatchQueue.global(qos: .userInitiated).async {
            do {
                let documentsDirectory = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
                let allFiles = try FileManager.default.contentsOfDirectory(at: documentsDirectory, includingPropertiesForKeys: nil)

                // 找到所有 onews_*.json 文件
                let newsJSONURLs = allFiles
                    .filter { $0.lastPathComponent.starts(with: "onews_") && $0.pathExtension == "json" }

                guard !newsJSONURLs.isEmpty else {
                    // 【双语化错误提示】
                    let errorMsg = currentLangIsEnglish 
                        ? "No news data found in local storage.\nPlease go back and sync resources first."
                        : "本地未发现新闻数据。\n请先返回主页同步资源。"
                    throw NSError(domain: "AppError", code: 1, userInfo: [NSLocalizedDescriptionKey: errorMsg])
                }

                // 使用字典去重：Key 是 ID，Value 是 Name
                // 如果同一个 ID 对应多个 Name (比如不同日期的文件改名了)，我们取最新的那个（这里简化为取扫描到的最后一个）
                var sourceMap = [String: String]()
                let decoder = JSONDecoder()

                for url in newsJSONURLs {
                    guard let data = try? Data(contentsOf: url),
                          let decoded = try? decoder.decode([String: [Article]].self, from: data) else {
                        continue
                    }

                    for (fileKeyName, articles) in decoded {
                        if let firstArticle = articles.first, let sourceId = firstArticle.source_id, !sourceId.isEmpty {
                            // 【核心修改】如果有映射，使用映射名；否则使用文件里的 Key
                            // 现在 mappings 变量已经存在了，不会报错
                            let displayName = mappings[sourceId] ?? fileKeyName
                            sourceMap[sourceId] = displayName
                        }
                    }
                }

                // 转换为数组并按名称排序
                let sortedSources = sourceMap.map { (id: $0.key, name: $0.value) }
                    .sorted { $0.name < $1.name }

                DispatchQueue.main.async {
                    self.allAvailableSources = sortedSources
                    self.isLoading = false
                }
            } catch {
                DispatchQueue.main.async {
                    self.errorMessage = error.localizedDescription
                    self.isLoading = false
                }
            }
        }
    }
}

