            await MainActor.run {
                isDownloadingImages = false
                selectedArticleItem = (article, sourceName)
                isNavigationActive = true
            }
        } catch {
            await MainActor.run {
                isDownloadingImages = false
                errorMessage = "\(Localized.fetchFailed): \(error.localizedDescription)"
                showErrorAlert = true
            }
        }
