                let isSuccess = try await authManager.purchaseSubscription()

                await MainActor.run {
                    isPurchasing = false

                    if isSuccess {
                        // 只有明确成功时，才关闭页面
                        print("支付成功，关闭订阅页面")
                        dismiss()
                    } else {
                        // 如果是取消(.userCancelled)或挂起，保持页面打开
                        print("用户取消或未完成支付，保留订阅页面")
                        // 这里不需要做任何操作，SubscriptionView 会继续显示
                    }
                }
            } catch {
                await MainActor.run {
                    isPurchasing = false
                    errorMessage = error.localizedDescription
                    showError = true
                }
            }
        }
    }

    // 【修改】处理恢复购买：先检查登录
    private func performRestore() {
        // 1. 检查是否已登录
        guard authManager.isLoggedIn else {
            showLoginSheet = true
            return
        }

        // 2. 已登录 -> 执行原有恢复逻辑
        isRestoring = true
        Task {
            do {
                try await authManager.restorePurchases()
                await MainActor.run {
                    isRestoring = false
                    // 【修改】恢复结果文案双语化
                    if authManager.isSubscribed {
                        restoreMessage = Localized.restoreSuccess
                    } else {
                        restoreMessage = Localized.restoreNotFound
                    }
                    showRestoreAlert = true
                }
            } catch {
                await MainActor.run {
                    isRestoring = false
                    // 使用专门的“恢复失败”词条
                    restoreMessage = "\(Localized.restoreFailed): \(error.localizedDescription)"
                    showRestoreAlert = true
                }
            }
        }
    }

    // 【修改】处理兑换逻辑：建议也加上登录检查
    private func handleRedeem() {
        guard !inviteCode.isEmpty else { return }

        // 建议加上：确保有 UserID 绑定
        guard authManager.isLoggedIn else {
            showLoginSheet = true
            return
        }

        isRedeeming = true
        Task {
            // ... (原有兑换逻辑保持不变)
            do {
                try await authManager.redeemInviteCode(inviteCode)
                await MainActor.run {
                    isRedeeming = false
                    inviteCode = ""
                    dismiss()
                }
            } catch {
                await MainActor.run {
                    isRedeeming = false
                    inviteCode = ""
                    errorMessage = error.localizedDescription
                    showError = true
                }
            }
        }
    }
}

import SwiftUI

// FloatingWord 结构体保持不变
struct FloatingWord: Identifiable {
    let id = UUID()
    let text: String
    var x: CGFloat      // 屏幕横向位置 (-1 到 1)
    var y: CGFloat      // 屏幕纵向位置 (-1 到 1)
    var z: CGFloat      // 深度 (0.0 最远, 1.0 最近)
    let color: Color
    let speed: CGFloat
    let angle: Double   // 飞行的角度
}

struct FloatingWordsView: View {
    @EnvironmentObject var resourceManager: ResourceManager
    @State private var words: [FloatingWord] = []
    @State private var sourceNames: [String] = []
    @State private var isActive = false

    // 颜色池：选择鲜艳且在黑白背景下都清晰的颜色
    private let colors: [Color] = [
        .blue, .purple, .pink, .orange, .mint, .teal, .indigo, .red
    ]

    var body: some View {
        GeometryReader { geometry in
            ZStack {
                // 使用 TimelineView 实现流畅的 60fps 动画
                TimelineView(.animation) { timeline in
                    Canvas { context, size in
                        for word in words {
                            // 计算透视效果
                            // 深度越深(z越小)，scale越小
                            let scale = 0.2 + (word.z * 2.5) // 0.2 -> 1.7 倍大小

                            // 模拟径向飞行：从中心向外扩散
                            // z 越大，离中心越远
                            let perspectiveFactor = word.z * 300 // 扩散范围
                            let drawX = (size.width / 2) + (CGFloat(cos(word.angle)) * perspectiveFactor * word.x)
                            let drawY = (size.height / 2) + (CGFloat(sin(word.angle)) * perspectiveFactor * word.y)

                            // 透明度逻辑：
                            // 刚出现时(z=0)透明度低，中间(z=0.5)最清楚，
                            // 撞向屏幕前(z>0.9)迅速消失以免遮挡视线
                            let opacity: Double
                            if word.z < 0.2 {
                                opacity = word.z * 5 // 淡入
                            } else if word.z > 0.8 {
                                opacity = 1.0 - ((word.z - 0.8) * 5) // 淡出
                            } else {
                                opacity = 1.0
                            }

                            // 绘制文字
                            if opacity > 0.01 {
                                var resolvedText = context.resolve(Text(word.text).fontWeight(.bold))
                                resolvedText.shading = .color(word.color)

                                context.opacity = opacity
                                context.draw(
                                    resolvedText,
                                    at: CGPoint(x: drawX, y: drawY),
                                    anchor: .center
                                )
                                context.transform = .init(scaleX: scale, y: scale)
                                // 注意：Canvas 的 transform 是累加的，这里简化处理，直接利用循环重绘
                            }
                        }
                    }
                }
            }
            .onAppear {
                isActive = true
                startAnimationLoop()
            }
            .onDisappear {
                isActive = false
            }
            .task {
                // 每次出现都去服务器拿最新的名字
                let names = await resourceManager.fetchSourceNames()
                await MainActor.run {
                    self.sourceNames = names
                }
            }
        }
        // 忽略点击，让用户可以点击穿透到底下的按钮（如果有重叠）
        .allowsHitTesting(false) 
    }

    private func startAnimationLoop() {
        // 使用 Timer 驱动数据更新（Canvas 负责绘图，这里负责逻辑）
        Timer.scheduledTimer(withTimeInterval: 0.016, repeats: true) { timer in
            guard isActive else {
                timer.invalidate()
                return
            }
            updateParticles()
        }
    }

    private func updateParticles() {
        // 1. 更新现有粒子位置
        var newWords: [FloatingWord] = []

        for var word in words {
            word.z += word.speed // 向前飞

            if word.z < 1.0 { // 还没飞出屏幕
                newWords.append(word)
            }
        }

        // 2. 生成新粒子 (如果当前粒子较少，且有数据源)
        if newWords.count < 12 && !sourceNames.isEmpty {
            // 随机决定是否生成，制造“参差不齐”的感觉
            if Double.random(in: 0...1) > 0.95 {
                let randomText = sourceNames.randomElement() ?? "ONews"
                let randomColor = colors.randomElement() ?? .blue

                // 随机生成飞行角度和起始偏移
                let randomAngle = Double.random(in: 0...(2 * .pi))

                let newWord = FloatingWord(
                    text: randomText,
                    x: CGFloat.random(in: 0.5...1.5), // 扩散幅度因子
                    y: CGFloat.random(in: 0.5...1.5),
                    z: 0.0, // 从最远处开始
                    color: randomColor,
                    speed: CGFloat.random(in: 0.002...0.006), // 速度差异
                    angle: randomAngle
                )
                newWords.append(newWord)
            }
        }

        self.words = newWords
    }
}

