    /// 从 Documents 中所有 onews_*.json 文件合并所有分组名（去重、排序）
    private func loadAvailableSources() {
        isLoading = true
        errorMessage = nil

        // 【修复】在进入后台线程前，先从 ResourceManager 获取映射表
        // 这样 mappings 变量就在闭包的作用域内了
        let mappings = resourceManager.sourceMappings
        let currentLangIsEnglish = self.isGlobalEnglishMode // 捕获当前语言状态用于闭包
        let useEnglish = self.isGlobalEnglishMode // 捕获主线程状态

        DispatchQueue.global(qos: .userInitiated).async {
            do {
                let documentsDirectory = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
                let allFiles = try FileManager.default.contentsOfDirectory(at: documentsDirectory, includingPropertiesForKeys: nil)

                // 找到所有 onews_*.json 文件
                let newsJSONURLs = allFiles
                    .filter { $0.lastPathComponent.starts(with: "onews_") && $0.pathExtension == "json" }

                guard !newsJSONURLs.isEmpty else {
                    // 【双语化错误提示】
                    let errorMsg = currentLangIsEnglish 
                        ? "No news data found in local storage.\nPlease go back and sync resources first."
                        : "本地未发现新闻数据。\n请先返回主页同步资源。"
                    throw NSError(domain: "AppError", code: 1, userInfo: [NSLocalizedDescriptionKey: errorMsg])
                }

                // 使用字典去重：Key 是 ID，Value 是 Name
                // 如果同一个 ID 对应多个 Name (比如不同日期的文件改名了)，我们取最新的那个（这里简化为取扫描到的最后一个）
                var sourceMap = [String: String]()
                let decoder = JSONDecoder()

                for url in newsJSONURLs {
                    guard let data = try? Data(contentsOf: url),
                          let decoded = try? decoder.decode([String: [Article]].self, from: data) else {
                        continue
                    }

                    for (fileKeyName, articles) in decoded {
                        if let firstArticle = articles.first, let sourceId = firstArticle.source_id, !sourceId.isEmpty {
                            // 【核心修改】如果有映射，使用映射名；否则使用文件里的 Key
                            // 现在 mappings 变量已经存在了，不会报错
                            let rawDisplayName = mappings[sourceId] ?? fileKeyName
                            // 根据当前语言模式，直接决定显示哪一段
                            // 注意：loadAvailableSources 闭包里用到了 self.isGlobalEnglishMode
                            // 建议在闭包外捕获一下: let useEnglish = self.isGlobalEnglishMode

                            let parts = rawDisplayName.components(separatedBy: "|")
                            let finalName: String
                            if useEnglish {
                                finalName = parts.count > 1 ? parts[1] : (parts.first ?? rawDisplayName)
                            } else {
                                finalName = parts.first ?? rawDisplayName
                            }

                            sourceMap[sourceId] = finalName
                        }
                    }
                }

                // 转换为数组并按名称排序
                let sortedSources = sourceMap.map { (id: $0.key, name: $0.value) }
                    .sorted { $0.name < $1.name }

                DispatchQueue.main.async {
                    self.allAvailableSources = sortedSources
                    self.isLoading = false
                }
            } catch {
                DispatchQueue.main.async {
                    self.errorMessage = error.localizedDescription
                    self.isLoading = false
                }
            }
        }
    }
}

// 处理标题是否有效的函数
function isValidTitle_Bloomberg(titleText) {
    const invalidPhrases = [
        'Illustration:', '/Bloomberg', 'Getty Images', '/AP Photo', '/AP',
        'Photos:', 'Photo illustration', 'Source:', '/AFP', 'NurPhoto',
        'SOurce:', 'WireImage', 'Podcast:'
    ];

    // 过滤掉仅包含 "LIVE" 的标题
    if (titleText.trim() === "LIVE") {
        return false;
    }

    // 过滤掉以 "Listen" 开头的标题
    if (titleText.trim().startsWith("Listen")) {
        return false;
    }

    if (invalidPhrases.some(phrase => titleText.includes(phrase))) {
        return false;
    }

    return titleText && !isTimeFormat(titleText);
}

// 判断是否为时间格式
function isTimeFormat(text) {
    if ((text.length === 4 || text.length === 5) && text.includes(':')) {
        const parts = text.split(':');
        return parts.every(part => !isNaN(parseInt(part)));
    }
    return false;
}

// 生成HTML内容
function generateHTML(data, source) {
    let html = `
<html>
<body>
  <table border='1'>
    <tr><th>Date</th><th>Title</th></tr>
`;

    data.forEach(row => {
        const clickableTitle = `<a href='${row[2]}' target='_blank'>${row[1]}</a>`;
        html += `<tr><td>${row[0]}</td><td>${clickableTitle}</td></tr>\n`;
    });

    html += `</table></body></html>`;
    return html;
}

// Bloomberg 抓取函数
function scrapeBloomberg() {
    const now = new Date();
    // 动态获取当前年份 (例如 2026)
    const currentYear = now.getFullYear();

    const currentDatetime = `${now.getFullYear()}_${String(now.getMonth() + 1).padStart(2, '0')}_${String(now.getDate()).padStart(2, '0')}_${String(now.getHours()).padStart(2, '0')}`;

    // 【修改点 1】：使用 currentYear 变量替换写死的 /2026
    const links = document.querySelectorAll(`a[href*='/${currentYear}']`);

    const newRows = [];

    links.forEach(link => {
        const href = link.href;
        let titleText = link.textContent.trim();

        if (titleText.startsWith("Newsletter: ")) {
            titleText = titleText.substring(11);
        }

        // 【修改点 2】：过滤视频链接时也使用动态年份
        if (href.includes(`/videos/${currentYear}`) || href.includes('/podcast')) {
            return;
        }

        if (isValidTitle_Bloomberg(titleText) && href) {
            newRows.push([currentDatetime, titleText, href]);
        }
    });

    if (newRows.length > 0) {
        const html = generateHTML(newRows, 'Bloomberg');
        const blob = new Blob([html], { type: 'text/html' });
        const url = URL.createObjectURL(blob);
        const timestamp = now.toLocaleString('zh-CN', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false
        }).replace(/[/: ]/g, '_');

        chrome.runtime.sendMessage({
            action: "downloadHTML",
            url: url,
            filename: `bloomberg_${timestamp}.html`
        });
    }
}

// reuters 抓取函数
function scrapeReuters() {
    const now = new Date();
    // 动态获取当前年份
    const currentYear = now.getFullYear();

    const currentDatetime = [
        now.getFullYear(),
        String(now.getMonth() + 1).padStart(2, '0'),
        String(now.getDate()).padStart(2, '0'),
        String(now.getHours()).padStart(2, '0'),
    ].join('_');

    // 【修改点】：使用 currentYear 变量替换写死的 -2026-
    // 路透社的链接通常是 ...-title-YYYY-MM-DD/，所以包含 -2026- 是合理的特征
    const allLinks = Array.from(
        document.querySelectorAll(`a[href*='-${currentYear}-']`)
    );

    // 要排除的路径片段
    const excludePaths = ['/podcasts/', '/sports/', '/africa/'];
    const seen = new Set();
    const newRows = [];

    allLinks.forEach(link => {
        const href = link.href;

        // 1) 排除“媒体图片”链接
        if (link.dataset.testid === 'MediaImageLink') return;

        // 2) 排除带 <img> 的链接
        if (link.querySelector('img')) return;

        // 3) 排除特定板块的链接
        if (excludePaths.some(p => href.includes(p))) return;

        // 4) 去重
        if (seen.has(href)) return;
        seen.add(href);

        // 5) 提取标题
        let titleText = '';
        // 优先 span[data-testid="TitleHeading"]
        const heading = link.querySelector("[data-testid='TitleHeading']");
        if (heading) {
            titleText = heading.textContent.trim();
        }
        // 万一有 <a data-testid="Title">…</a>
        else if (link.dataset.testid === 'Title') {
            titleText = link.textContent.trim();
        }
        // 兜底：任何文本
        else {
            titleText = link.textContent.trim();
        }

        if (titleText) {
            newRows.push([currentDatetime, titleText, href]);
        }
    });

    if (newRows.length === 0) return;

    // --------- 和你现有的 downloadHTML 部分一模一样 ---------
    const html = generateHTML(newRows, 'Reuters');
    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const timestamp = now
        .toLocaleString('zh-CN', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false
        })
        .replace(/[/: ]/g, '_');

    chrome.runtime.sendMessage({
        action: "downloadHTML",
        url,
        filename: `reuters_${timestamp}.html`
    });
}

// WSJ 抓取函数
function scrapeWSJ(shouldDownload = true) {
    const now = new Date();
    const currentDatetime = `${now.getFullYear()}_${String(now.getMonth() + 1).padStart(2, '0')}_${String(now.getDate()).padStart(2, '0')}_${String(now.getHours()).padStart(2, '0')}`;
    const newRows = [];
    const hostname = window.location.hostname;

    // 添加新的选择器 css-g4pnb7
    const titleElements = document.querySelectorAll('h3.css-fsvegl a, article h2 a, .WSJTheme--headline--7VCzo7Ay a, .css-g4pnb7, .css-2pp34t');

    titleElements.forEach(titleElement => {
        const href = titleElement.href;

        // 跳过包含 livecoverage 或 buyside 的链接
        if (!href || href.toLowerCase().includes('livecoverage') || href.toLowerCase().includes('wsj.com/buyside') || href.toLowerCase().includes('wsj.com/video') || href.toLowerCase().includes('wsj.com/sports')) {
            return;
        }

        // 检查链接域名，只保留 wsj.com 的链接
        try {
            const url = new URL(href);
            if (!url.hostname.includes('wsj.com')) {
                return;
            }
        } catch (e) {
            // 如果 URL 解析失败，跳过这个链接
            return;
        }

        let titleText = titleElement.innerText.trim();

        // 移除阅读时间标记
        titleText = titleText.replace(/\d+ min read/g, '').trim();

        if (titleText && href) {
            newRows.push([currentDatetime, titleText, href]);
        }
    });

    // 只有当 shouldDownload 为 true 且有内容时才下载
    if (shouldDownload && newRows.length > 0) {
        const html = generateHTML(newRows, 'WSJ');
        const blob = new Blob([html], { type: 'text/html' });
        const url = URL.createObjectURL(blob);
        const timestamp = now.toLocaleString('zh-CN', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false
        }).replace(/[/: ]/g, '_');

        // 根据域名决定文件名前缀
        const prefix = hostname.includes('cn.wsj.com') ? 'cnwsj_' : 'wsj_';

        chrome.runtime.sendMessage({
            action: "downloadHTML",
            url: url,
            filename: `${prefix}${timestamp}.html`
        });
    }

    return newRows.length;
}

// FT 抓取函数 (新增)
function scrapeFT() {
    const now = new Date();
