def add_css_to_soup(soup, css_string):
    """将CSS字符串添加到BeautifulSoup对象的<head>中"""
    if not soup.head:
        head_tag = soup.new_tag("head")
        if soup.html: 
            soup.html.insert(0, head_tag)
        else: 
            soup.insert(0, head_tag)
    else:
