@MainActor
class AppBadgeManager: ObservableObject {

    // 新增异步版本的权限请求
    func requestAuthorizationAsync() async {
        await withCheckedContinuation { continuation in
            UNUserNotificationCenter.current().requestAuthorization(options: [.badge]) { granted, error in
                Task { @MainActor in
                    if granted {
                        print("用户已授予角标权限。")
                    } else {
                        print("用户未授予角标权限。")
                    }
                    continuation.resume()
                }
            }
        }
    }

    // 保留原有的同步版本,供其他地方使用
    func requestAuthorization() {
        UNUserNotificationCenter.current().requestAuthorization(options: [.badge]) { granted, error in
            DispatchQueue.main.async {
                if granted {
                    print("用户已授予角标权限。")
                } else {
                    print("用户未授予角标权限。")
                }
            }
        }
    }

    func updateBadge(count: Int) {
        var backgroundTask: UIBackgroundTaskIdentifier = .invalid
        backgroundTask = UIApplication.shared.beginBackgroundTask(withName: "updateBadgeCount") {
            print("后台任务时间耗尽,强制结束角标更新任务。")
            if backgroundTask != .invalid {
                UIApplication.shared.endBackgroundTask(backgroundTask)
                backgroundTask = .invalid
            }
        }

        let badgeCount = max(0, count)
        UNUserNotificationCenter.current().setBadgeCount(badgeCount) { error in
            if let error = error {
                print("【角标更新失败】: \(error.localizedDescription)")
            } else {
                print("【角标更新成功】应用角标已(重新)设置为: \(badgeCount)")
            }

            if backgroundTask != .invalid {
                print("角标更新操作完成,结束后台任务。")
                UIApplication.shared.endBackgroundTask(backgroundTask)
                backgroundTask = .invalid
            }
        }
    }
}

import sys
import re

def count_chinese_characters(text):
    # 使用正则表达式匹配所有中文字符 (Unicode 范围: \u4e00-\u9fff)
    chinese_pattern = re.compile(r'[\u4e00-\u9fff]')
    chinese_chars = chinese_pattern.findall(text)
    return len(chinese_chars)

if __name__ == "__main__":
    # 从命令行参数获取文本
    if len(sys.argv) > 1:
        content = sys.argv[1]
        count = count_chinese_characters(content)
        # 如果超过 50 个汉字，输出 true，否则输出 false
        if count > 50:
            print("true")
        else:
            print("false")
    else:
        print("false")

